    #[test]
    fn live_sessions_group_context_menu_exposes_close_all_action() {
        // The Live Sessions group row offers exactly one action: Close All. Asserted
        // against the row-menu SSOT (which the overlay renders and the ALT layer
        // declares) rather than by scraping the rsx for a literal — the menu is
        // built from `row_menu_items` now, so the list IS the contract.
        let row = BrowserRow {
            kind: BrowserRowKind::Group,
            full_path: "__live_sessions__".to_string(),
            label: "Live Sessions".to_string(),
            detail_label: String::new(),
            document_kind: None,
            group_kind: None,
            session_title: None,
            depth: 0,
            host_label: String::new(),
            descendant_sessions: 2,
            expanded: true,
            session_id: None,
            session_cwd: None,
            session_kind: None,
        };
        let items = row_menu_items(&row, &[], None, &[], 0, false, false, RowSetMenuRole::None);
        let close_all = items
            .iter()
            .find(|item| item.id == "close-all-live-sessions")
            .expect("Live Sessions offers Close All");
        assert_eq!(close_all.label, "Close All…");
        assert!(close_all.destructive);
        // …and it is the ONLY action on that row (no rename, no launch, no delete).
        let actions: Vec<&str> = items
            .iter()
            .filter(|item| !item.separator)
            .map(|item| item.id.as_str())
            .collect();
        assert_eq!(actions, vec!["close-all-live-sessions"]);
        let source = SHELL_SOURCE;
        assert!(source.contains("open_live_sessions_close_all_dialog"));
    }

    #[test]
    fn live_session_close_is_silent_on_success_and_preserves_focus() {
        // Source-scraping invariant test (matches the existing pattern in this
        // module). Note: the searched substrings use real quotes / embedded
        // newlines, which only match the actual code below — NOT this test's own
        // escaped (\" , \n) literals — so the assertions are not self-satisfying.
        let source = SHELL_SOURCE;
        // The post-close daemon snapshot PRESERVES the optimistic local focus for a
        // live-session close (preserve_focus = pending.live_session_close), so the
        // view cannot bounce back to the just-closed session. This is the core fix.
        assert!(source.contains(
            "Ok(result),\n                        pending.live_session_close,\n                        \"delete_finished\","
        ));
        // The success toast is gated OFF for a live-session close (silent on
        // success — the row already vanished); stored-item deletes keep their toast.
        assert!(source.contains(
            "if !pending.live_session_close {\n                    let (title, message) = delete_success_notification_text(&pending, deleted);"
        ));
        // Failures still notify (the Err arms push an error notification).
        assert!(source.contains("\"Delete Failed\""));
        assert!(source.contains("\"Delete Task Failed\""));
    }

