    #[test]
    fn terminal_eval_script_is_parseable_as_dioxus_async_function_body() {
        let node_available = Command::new("node").arg("--version").output();
        if node_available.is_err() {
            eprintln!("skipping terminal eval script syntax check because node is unavailable");
            return;
        }
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, false);
        let tmp_dir = std::env::current_dir()
            .expect("current dir")
            .join("target")
            .join("tmp")
            .join("terminal-eval-script-syntax");
        std::fs::create_dir_all(&tmp_dir).expect("create terminal eval syntax tmp dir");
        let script_path = tmp_dir.join("terminal-eval-script.js");
        std::fs::write(&script_path, script).expect("write terminal eval script");
        let output = Command::new("node")
            .arg("-e")
            .arg(
                "const fs = require('fs'); const source = fs.readFileSync(process.argv[1], 'utf8'); const AsyncFunction = async function() {}.constructor; new AsyncFunction('dioxus', source);",
            )
            .arg(&script_path)
            .output()
            .expect("run node syntax check");
        assert!(
            output.status.success(),
            "terminal eval script must parse as the Dioxus AsyncFunction body: stdout={} stderr={}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }
    #[test]
    fn terminal_eval_script_rejects_stale_input_reclaim_for_inactive_hosts() {
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        assert!(script.contains("const hostOwnsActiveTerminalInput = () => {"));
        // A visible document surface must stand the terminal down so its
        // focus-reclaim cascade cannot steal focus from the shell-DOM editor.
        assert!(script.contains("const documentSurfaceOwnsViewport = () => {"));
        assert!(script.contains(
            "String(host.getAttribute('data-document-surface-owns-viewport') || '')"
        ));
        assert!(
            script.contains("if (documentSurfaceOwnsViewport()) {"),
            "hostOwnsActiveTerminalInput must yield to a covering document surface"
        );
        assert!(script.contains("setInputEnabled(false, false);"));
        assert!(script.contains("const requestedEnabled = Boolean(enabled);"));
        assert!(script.contains(
            "const canOwnActiveInput = !requestedEnabled || hostOwnsActiveTerminalInput();"
        ));
        assert!(script.contains("host.style.pointerEvents = 'auto';"));
        assert!(
            script.contains("const shouldHandleWheel = (event) => {")
                && script.contains("if (!event || !hostOwnsActiveTerminalInput()) {")
        );
        assert!(
            script.contains("const pasteEventBelongsToTerminal = (event) => {")
                && script
                    .contains("if (!event || !inputEnabled || !hostOwnsActiveTerminalInput()) {"),
            "paste stays user-input gated while wheel scrolling can work in read-only focus states"
        );
    }

    #[test]
    fn terminal_eval_script_forwards_protocol_replies_while_user_input_is_gated() {
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, false);
        assert!(script.contains("const terminalDataBypassesInputGate = (data) => {"));
        assert!(script.contains("/^\\x1b\\[[0-9;?]*[Rcnu]$/"));
        assert!(script.contains("/^\\x1b\\][0-9]+;.*(?:\\x07|\\x1b\\\\)$/"));
        assert!(script.contains("/^\\x1b\\[[IO]$/"));
        assert!(script.contains("const protocolBypass = terminalDataBypassesInputGate(data);"));
        assert!(script.contains("if (!inputEnabled && !protocolBypass) {"));
        assert!(script.contains("if (protocolBypass) {"));
        assert!(script.contains("protocolDataEventCount"));
        assert!(script.contains("ignoredDataEventCount"));
    }

    #[test]
    fn a_web_surface_geometry_eval_samples_covers_and_maintains_the_transparency_chain() {
        // Phase F tripwires: the ONE geometry sample must carry the covers
        // for the input region (a toast over a page must stay clickable),
        // and it must NEVER mutate the DOM — the 2026-07-19 incident came
        // from this eval clearing shared ancestor backgrounds inline
        // (app-wide breakage, unrestorable once the eval stops running).
        let js = WEB_SURFACE_GEOMETRY_EVAL_JS;
        assert!(
            js.contains("querySelectorAll('[data-covers-web-surface]')"),
            "covers must be sampled in the SAME eval as page rects (SSOT)"
        );
        assert!(
            js.contains("covers: covers"),
            "covers must ride the same send as the page rects"
        );
        assert!(
            !js.contains("style.background") && !js.contains("ugCleared"),
            "the geometry eval SAMPLES ONLY — no DOM mutation, ever \
             (incident-f0-transparency-chain-app-wide-break)"
        );
        // F.1: chrome CLAIMS are dead under glass (the chrome floats over the
        // page as a cover; the page rect must not move on reveal) and alive in
        // legacy stacking (moving the page is the only visible reveal there).
        // Both halves are load-bearing — losing the underGlass gate
        // re-introduces the reveal reflow; losing the claim breaks legacy.
        assert!(
            js.contains("const underGlass = document.documentElement.getAttribute('data-under-glass') === '1';"),
            "the claims must be gated on the under-glass stamp"
        );
        assert!(
            js.contains("if (underGlass) { return [0, 0]; }"),
            "under glass no chrome edge may claim anything"
        );
        assert!(
            js.contains("chrome: chrome,"),
            "legacy keeps the claims, and they ride the same send as the rects"
        );
    }

    // F.1 T8 tripwire: the synchronous cover observer must sample the SAME
    // covers vocabulary as the tick's geometry eval (one selector, two
    // cadences), and — like the eval — must never mutate the DOM.
    #[test]
    fn a_cover_observer_samples_the_same_covers_and_never_mutates() {
        let js = WEB_SURFACE_COVER_OBSERVER_JS;
        assert!(
            js.contains("querySelectorAll('[data-covers-web-surface]')"),
            "the observer and the geometry eval must share the covers selector"
        );
        assert!(
            js.contains("ResizeObserver") && js.contains("MutationObserver"),
            "mount/unmount (mutation) AND resize (the titlebar reveal \
             transition) must both push"
        );
        assert!(
            !js.contains("style.") && !js.contains("setAttribute"),
            "the cover observer SAMPLES ONLY — no DOM mutation, ever"
        );
    }

    // F.1 T10 tripwire: under glass a modal no longer stashes the surface —
    // it relies on the full-window transient cover for input. Every modal
    // `has_modal_over_viewport` counts must therefore also open the
    // transient cover, or it becomes a click-through window over a page.
    #[test]
    // §12.3. The user's failing chain was ALT,E,L -> ALT,J,up -> ALT,E,X, which
    // opens a modal that then accepted NO keys, so a keyboard-only flow had to
    // finish at the mouse. The bridge only captured while the ALT overlay was up,
    // and the overlay closes the moment a chord dispatches.
    #[test]
    fn a_modal_owns_the_dialog_keys_even_with_the_alt_overlay_closed() {
        let script = keytip_bridge_js(&KeymapConfig::default());

        assert!(
            script.contains("function modalOpen()"),
            "the bridge needs its own authoritative modal probe, like overlayOpen()"
        );
        assert!(
            script.contains("data-yggterm-modal-open"),
            "modal detection must read the marker Rust renders from render_top_modal"
        );
        assert!(
            script.contains("modal_key:"),
            "a dialog key must arrive as its own message, never as a chord char"
        );
        // The trap: the copy-edit dialog holds a text input. Capturing Backspace
        // globally would eat the user's editing.
        assert!(
            script.contains("function editingText()"),
            "Backspace/Enter belong to a focused text field, not to the dialog"
        );
        assert!(
            script.contains("if (mk !== 'Escape' && editingText()) { return; }"),
            "Escape must still dismiss from inside a text field, Backspace must not"
        );
    }

    /// The CLI-installation modal is a first-class member of the precedence
    /// list, not a special case bolted beside it.
    #[test]
    fn the_cli_install_modal_owns_the_keys_when_it_is_the_only_one_up() {
        assert_eq!(
            top_modal_of(false, false, false, true, false, false, false, false, false, false, false, false),
            Some(TopModal::CliInstall)
        );
        assert_eq!(TopModal::CliInstall.kind(), "cli-install");
        assert_eq!(TopModal::CliInstall.scope_label(), "CLI Install");
    }

    /// Two Settings-raised modals can be flagged at once (the rail can open
    /// either). The order must be DECIDED rather than incidental, or Enter lands
    /// in whichever one the struct happened to list first.
    #[test]
    fn launch_flags_outranks_cli_install_when_both_are_flagged() {
        assert_eq!(
            top_modal_of(false, false, true, true, false, false, false, false, false, false, false, false),
            Some(TopModal::LaunchFlags),
            "the deeper modal keeps the keys until it is dismissed"
        );
    }

    /// The owner asked for the install button to sit AFTER the launch-flags
    /// button in the settings rail. Locked against the source because the two
    /// are adjacent siblings in one `rsx!` block: a later edit that inserts a
    /// section between them, or reorders them, changes the thing that was asked
    /// for while every behavioural test still passes.
    #[test]
    fn the_cli_install_button_follows_the_launch_flags_button_in_the_settings_rail() {
        let source = include_str!("right_rail.rs");
        let flags = source
            .find("LaunchFlagsSettingsSection {")
            .expect("the launch-flags section is mounted in the rail");
        let install = source
            .find("CliInstallSettingsSection {")
            .expect("the CLI-install section is mounted in the rail");
        assert!(
            flags < install,
            "the install button must follow the flags button, as asked"
        );
        let between = &source[flags..install];
        assert_eq!(
            between.matches("SettingsSection {").count(),
            1,
            "nothing may be inserted between the two buttons: {between}"
        );
    }

    /// The local column answers the LAUNCH-parity probe when it has landed,
    /// and only falls back to the process-`PATH` walk before the first probe
    /// returns. The regression this locks: the modal once reported CLIs as
    /// missing that the machine had installed and was RUNNING, because the
    /// managed bin dir a launch prepends is not in the GUI's desktop `PATH` —
    /// and a freshly installed CLI could never flip its chip.
    #[test]
    fn the_local_cli_column_prefers_the_launch_parity_probe_over_the_process_path() {
        // The launch-parity report says codex is present. The process-`PATH`
        // fallback (binary_on_process_path) may say anything at all — the
        // report wins either way.
        let report = vec![yggterm_core::cli_install::CliPresenceReport {
            slug: "codex".to_string(),
            present: true,
            version: Some("9.9.9".to_string()),
        }];
        let machines = cli_install_machines(&[], Some(&report));
        let local = machines
            .iter()
            .find(|machine| machine.machine_key == LOCAL_CLI_MACHINE_KEY)
            .expect("the local machine is always listed first");
        let codex = local
            .rows
            .iter()
            .find(|row| row.slug == "codex")
            .expect("codex is a registered CLI");
        assert!(
            codex.presence.is_present(),
            "the probe report must drive the local column"
        );
        // A slug absent from the report is Unknown, never Absent — an
        // incomplete probe must not read as "install it".
        let missing = local
            .rows
            .iter()
            .find(|row| row.slug != "codex")
            .expect("the registry has more than one CLI");
        assert!(
            !missing.presence.is_present() && !matches!(missing.presence, yggterm_core::cli_install::CliPresence::Absent),
            "a slug the report does not mention must stay Unknown, got {:?}",
            missing.presence
        );

        // Before the first probe lands, the fallback column still renders.
        let fallback = cli_install_machines(&[], None);
        assert_eq!(fallback.len(), 1);
    }

    // ONE precedence list decides both "is a modal up" and "who gets the Enter".
    #[test]
    fn modal_precedence_is_topmost_first_and_has_a_single_owner() {
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, false, false, false, false, false, false),
            None
        );
        // Each flag alone names its own dialog, in paint order.
        assert_eq!(
            top_modal_of(true, false, false, false, false, false, false, false, false, false, false, false),
            Some(TopModal::KeymapEditor)
        );
        assert_eq!(
            top_modal_of(false, true, false, false, false, false, false, false, false, false, false, false),
            Some(TopModal::ThemeEditor)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, true, false, false, false, false, false, false),
            Some(TopModal::MediaCapture)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, true, false, false, false, false, false),
            Some(TopModal::Fido2)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, false, true, false, false, false, false),
            Some(TopModal::Delete)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, false, false, true, false, false, false),
            Some(TopModal::CopyEdit)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, false, false, false, true, false, false),
            Some(TopModal::ClassicTabsSwitch)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, false, false, false, false, false, true),
            Some(TopModal::StripDropdown)
        );
        // Stacked: the topmost-rendered dialog wins the keyboard. The KeyTips
        // editor paints at z-index 500, above every dialog, so it wins outright.
        assert_eq!(
            top_modal_of(true, true, true, false, false, true, true, true, true, true, false, true),
            Some(TopModal::KeymapEditor)
        );
        // ⛔ A capture prompt outranks every dialog below the two editors. Both
        // it and the passkey ceremony are raised by a PAGE at a moment the user
        // did not choose; the one that hands over a camera has to be the one the
        // keyboard reaches, or Escape would dismiss the wrong dialog and leave
        // the engine blocked on this one.
        assert_eq!(
            top_modal_of(false, false, false, false, false, true, true, true, true, true, false, true),
            Some(TopModal::MediaCapture)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, true, true, true, true, false, true),
            Some(TopModal::Fido2)
        );
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, false, true, true, true, false, true),
            Some(TopModal::Delete)
        );
        // …and a strip dropdown is the FLOOR of that list: a dialog raised while
        // one is open owns the screen over it, never the other way round.
        assert_eq!(
            top_modal_of(false, false, false, false, false, false, false, false, false, true, false, true),
            Some(TopModal::ClassicTabsSwitch)
        );

        // And `has_modal_over_viewport` must be exactly "something is on top",
        // so the two can never drift apart.
        let mut shell = shell_with_contribution("local://ws", 1_000);
        assert!(!shell.has_modal_over_viewport());
        assert_eq!(shell.top_modal(), None);
        shell.pending_classic_tabs_switch = true;
        assert!(shell.has_modal_over_viewport());
        assert_eq!(shell.top_modal(), Some(TopModal::ClassicTabsSwitch));
    }

    #[test]
    fn every_over_viewport_modal_opens_the_transient_cover() {
        let mut shell = shell_with_contribution("local://ws", 1_000);
        assert!(!shell.has_modal_over_viewport());
        assert!(!chrome_transient_over_viewport(&shell.snapshot()));

        let cases: Vec<(&str, Box<dyn Fn(&mut ShellState)>)> = vec![
            // A capture prompt is raised over whatever is on screen, and under
            // glass a native web surface composites ABOVE all DOM — so without
            // the transient cover the "may this page use your camera?" dialog
            // would be a click-through window the user cannot reach.
            (
                "pending_media_capture",
                Box::new(|shell: &mut ShellState| {
                    shell.pending_media_capture = Some(PendingMediaCaptureDialog {
                        request_id: 7,
                        surface_id: 1,
                        session_path: Some("local://ws".to_string()),
                        origin: Some("https://example.test".to_string()),
                        display: "https://example.test".to_string(),
                        audio: false,
                        video: true,
                    });
                }),
            ),
            (
                "pending_delete",
                Box::new(|shell: &mut ShellState| {
                    shell.pending_delete = Some(PendingDeleteDialog {
                        document_paths: Vec::new(),
                        group_paths: Vec::new(),
                        session_paths: Vec::new(),
                        ssh_machine_keys: Vec::new(),
                        labels: Vec::new(),
                        hard_delete: false,
                        live_session_close: false,
                        live_session_bulk_close: false,
                        live_session_unkept_paths: Vec::new(),
                    });
                }),
            ),
            (
                "copy_edit_dialog",
                Box::new(|shell: &mut ShellState| {
                    shell.copy_edit_dialog = Some(CopyEditDialog {
                        field: CopyEditField::Title,
                        session_path: "local://ws".to_string(),
                        session_id: String::new(),
                        cwd: String::new(),
                        title: String::new(),
                        value: String::new(),
                    });
                }),
            ),
            (
                "pending_classic_tabs_switch",
                Box::new(|shell: &mut ShellState| {
                    shell.pending_classic_tabs_switch = true;
                }),
            ),
            // The two CLASSIC-STRIP dropdowns. They joined `top_modal` because
            // there is no DOM band below the strip to place them in, so the
            // legacy page has to be stashed — and the moment they count as a
            // modal, the F.1 T10 tripwire applies to them too.
            (
                "web_tab_overflow_open",
                Box::new(|shell: &mut ShellState| {
                    // Through the affordance, not the raw flag: the dropdown
                    // exists only while a tab is filed, and the flag is gated on
                    // exactly that (see
                    // `a_folder_overflow_dropdown_cannot_outlive_its_affordance`).
                    seed_web_surface_with_filed_tab(shell, "local://ws");
                    shell.toggle_web_tab_overflow();
                }),
            ),
            (
                "web_profile_switcher(strip)",
                Box::new(|shell: &mut ShellState| {
                    shell.web_profile_switcher = Some(WebProfileSwitcher {
                        session_path: "local://ws".to_string(),
                        current_profile: "default".to_string(),
                        profiles: vec!["default".to_string()],
                        anchor: WebSurfaceChromeAnchor::Strip,
                        position: (820.0, 90.0),
                    });
                }),
            ),
            // The two full-window EDITORS. They joined `top_modal` so the ALT
            // layer could operate them (§4 — a dialog is a scope), and the two
            // lists answer the same question, so they have to be here as well:
            // over a legacy web surface an unstashed editor is invisible.
            (
                "keymap_editor_open",
                Box::new(|shell: &mut ShellState| {
                    shell.open_keymap_editor();
                }),
            ),
            (
                "theme_editor_open",
                Box::new(|shell: &mut ShellState| {
                    shell.set_theme_editor_open(true);
                }),
            ),
        ];
        for (name, arm) in cases {
            let mut shell = shell_with_contribution("local://ws", 1_000);
            arm(&mut shell);
            assert!(
                shell.has_modal_over_viewport(),
                "{name}: expected an over-viewport modal"
            );
            assert!(
                chrome_transient_over_viewport(&shell.snapshot()),
                "{name}: an over-viewport modal MUST open the transient cover \
                 (click-through modal under glass otherwise)"
            );
        }
        let _ = &mut shell;
    }

    #[test]
    fn a_under_glass_css_clears_every_backing_wrapper_and_holes_the_app_bg_layer() {
        // F.0.1: the probe-confirmed opaque chain over a page hole was
        // wrapper (web_frame_bg) → material frame → shell root. Every one of
        // them must be handled here, every rule keyed on the root stamp so a
        // probe demotion restores the lot with no re-render.
        let css = WEB_UNDER_GLASS_CSS;
        for needle in [
            "[data-web-surface-owns-viewport=\"true\"] { background: transparent !important; }",
            // The boring-reveal covers are siblings of .xterm inside the
            // host — hiding .xterm alone leaves them painting a stale
            // terminal frame over the page hole for seconds on switch.
            "[data-web-surface-owns-viewport=\"true\"] .yggterm-reveal-ghost { visibility: hidden; }",
            "[data-web-surface-owns-viewport=\"true\"] .yggterm-cold-mount-veil { visibility: hidden; }",
            "[data-ws-frame=\"1\"] { background: transparent !important; }",
            "[data-ws-overlay=\"1\"] { background: transparent !important; }",
            // F.1 molded frame: the interim 4px inset dies under glass — the
            // page fills to the frame edge and the rounded paint hole molds
            // its corners instead.
            "[data-ws-page] { background: transparent !important; margin: 0 !important; }",
            "[data-ws-pinned-session] { background: transparent !important; }",
            "#yggterm-shell-root { background: transparent !important; }",
        ] {
            assert!(css.contains(needle), "missing under-glass clear: {needle}");
        }
        // The shared material frame loses color+gradient only — its exported
        // CSS variables stay (titlebar and panels read them).
        assert!(css.contains(
            "[data-yggterm-shell=\"1\"] { background-color: transparent !important; background-image: none !important; }"
        ));
        // The dedicated background layer takes the holes, nothing else does.
        assert!(css.contains(
            "[data-yggterm-app-bg=\"1\"] { clip-path: var(--yggterm-under-glass-holes, none);"
        ));
        for line in css.lines().filter(|line| !line.trim().is_empty()) {
            assert!(
                line.starts_with(":root[data-under-glass=\"1\"]"),
                "under-glass rule not keyed on the root stamp: {line}"
            );
        }
        // The covered-host pointer stand-down is NOT under-glass business and is
        // not keyed on the stamp, so it lives in its own sheet — putting it here
        // is what broke the invariant above.
        assert!(
            DOCUMENT_SURFACE_STANDDOWN_CSS.contains(
                "[data-document-surface-owns-viewport=\"true\"] { pointer-events: none; }"
            ),
            "a document surface covering the host must make the host unclickable"
        );
        assert!(
            !css.contains("data-document-surface-owns-viewport"),
            "document-surface rules do not belong in the under-glass sheet"
        );
    }

    // Under glass the backgrounding stash is SOFT: the webview stays
    // attached (demoted to the bottom of the page stack) and composited
    // under the opaque glass, so switch-back is "cut the hole" over
    // already-live pixels — no GTK re-map, no WebKit re-composite, no
    // seconds-long terminal/backdrop flash on every switch to a web
    // session. Legacy stacking MUST keep the detach: a legacy surface
    // draws above all DOM and only unmapping clears its pixels (the
    // stuck-composite / reload-white family).
    /// ⚠ A UNIT TEST OF THE HELPER, NOT A CALL-SITE LOCK. It builds
    /// `web_surface_background_hold_ms_for`'s arguments itself, so it cannot see
    /// what the reconcile loop passes — which is where the defect was, and why
    /// reverting all four production call sites once left this suite green. The
    /// lock lives in `web_surface_reclaim_locks`
    /// (`a_surface_that_keeps_coming_back_stops_being_reaped_by_the_pass`). This
    /// stays because the threshold arithmetic is worth stating; do not cite it
    /// as proof that reclaim is wired.
    ///
    /// Reclaim that destroys a page which is immediately
    /// re-created reclaims nothing and costs a fresh WebKit process every cycle.
    /// Measured live before this guard existed: **166 `background_hold_expired`
    /// closes against 166 re-opens in fifteen minutes**, ~11 cycles a minute,
    /// one of the churned processes ballooning to 3.9 GB, on a host whose swap
    /// was 100% full — the reaper reacting to pressure it was itself creating,
    /// while the user could not hold keyboard focus long enough to type.
    ///
    /// So: pressure alone still reclaims fast (that is the feature), but a
    /// surface that has demonstrated it comes back must stop being a target.
    #[test]
    fn the_thrash_hold_helper_escalates_at_the_reopen_limit() {
        use crate::terminal_observe::ReclaimPosture::Pressured;
        let pressured_hold = web_surface_background_hold_ms_for(Some(600_000), Pressured, 0);
        assert_eq!(
            pressured_hold,
            Some(WEB_SURFACE_PRESSURED_BACKGROUND_HOLD_MS),
            "first reap under pressure must still be fast — that is the feature"
        );
        assert_eq!(
            web_surface_background_hold_ms_for(
                Some(600_000),
                Pressured,
                WEB_SURFACE_THRASH_REOPEN_LIMIT - 1
            ),
            Some(WEB_SURFACE_PRESSURED_BACKGROUND_HOLD_MS),
            "below the limit it is still an ordinary reclaim candidate"
        );
        let thrashing = web_surface_background_hold_ms_for(
            Some(600_000),
            Pressured,
            WEB_SURFACE_THRASH_REOPEN_LIMIT,
        );
        assert!(
            thrashing.is_some_and(|ms| ms > WEB_SURFACE_PRESSURED_BACKGROUND_HOLD_MS),
            "a surface reaped {} times in the window is demonstrably wanted; \
             reaping it again is the treadmill — got {thrashing:?} ms",
            WEB_SURFACE_THRASH_REOPEN_LIMIT,
        );
        // And the escalation must be per-surface, not global: a DIFFERENT
        // surface with no history is still reclaimed promptly, or one busy page
        // would switch reclaim off for everything.
        assert_eq!(
            web_surface_background_hold_ms_for(Some(600_000), Pressured, 0),
            Some(WEB_SURFACE_PRESSURED_BACKGROUND_HOLD_MS),
            "one thrashing surface must not spare every other surface"
        );
    }

    /// The counter that feeds the guard has to actually count, and it has to
    /// forget: a surface reaped twice yesterday is not thrashing today.
    #[test]
    fn the_reap_counter_is_per_surface_and_forgets_outside_the_window() {
        let a = ("live::treadmill-a".to_string(), 0u64);
        let b = ("live::treadmill-b".to_string(), 0u64);
        let t0 = 10_000_000_u64;
        assert_eq!(web_surface_note_reap(&a, t0), 1);
        assert_eq!(web_surface_note_reap(&a, t0 + 1_000), 2);
        assert_eq!(
            web_surface_recent_reaps(&b, t0 + 1_000),
            0,
            "reaps must be counted per surface, not globally"
        );
        // Past the window relative to the LAST entry, not the first — an
        // entry 119 s old is legitimately still inside a 120 s window.
        let later = t0 + 1_000 + WEB_SURFACE_THRASH_WINDOW_MS + 1;
        assert_eq!(
            web_surface_note_reap(&a, later),
            1,
            "entries older than the window must be forgotten, or a surface \
             reaped long ago would be exempt from reclaim forever"
        );
    }

    /// ⚠ Helper unit test, not a call-site lock — `web_surface_background_detach`
    /// is asked directly here, so it says nothing about which pressure reading
    /// the loop feeds it. That is
    /// `web_surface_reclaim_locks::the_reclaim_pass_reads_current_headroom_not_swap_history`.
    #[test]
    fn a_under_glass_backgrounding_never_detaches_the_webview() {
        // Legacy always detaches; under glass with no memory pressure keeps the
        // soft stash (attached, instant switch-back).
        assert!(web_surface_background_detach(false, false));
        assert!(!web_surface_background_detach(true, false));
    }

    #[test]
    fn under_glass_backgrounding_detaches_and_reclaims_under_memory_pressure() {
        // Pressure-triggered reclaim: under glass + genuinely short of memory, a
        // backgrounded surface DETACHES (unmap -> CPU throttled) and its hold
        // collapses to seconds so the destroy-on-hold branch reclaims its
        // memory instead of holding ~1.3 GB for ten minutes. Legacy is
        // unaffected (always detaches).
        assert!(web_surface_background_detach(true, true));
        assert!(web_surface_background_detach(false, true));
        // The pressured hold is the short reclaim window, whatever was
        // configured — asked of the POLICY, which is where the override lives
        // now (the config reader used to carry a second copy of it).
        for configured in [None, Some(600_000), Some(0)] {
            assert_eq!(
                web_surface_background_hold_ms_for(
                    configured,
                    crate::terminal_observe::ReclaimPosture::Pressured,
                    0
                ),
                Some(WEB_SURFACE_PRESSURED_BACKGROUND_HOLD_MS)
            );
        }
    }

    /// ⚠ NOT A CALL-SITE LOCK, despite what it used to claim. It computes
    /// `live.reclaim_pressured()` itself and hands the RESULT to the policy
    /// functions, so it can never observe which predicate the reconcile loop
    /// actually consults — the entire defect. It survived a revert of all four
    /// production call sites. What it still says honestly is that the two
    /// predicates DISAGREE on the live host's real `/proc/meminfo`, which is the
    /// fixture the real lock is built on
    /// (`web_surface_reclaim_locks::the_reclaim_pass_reads_current_headroom_not_swap_history`).
    #[test]
    fn the_two_pressure_predicates_disagree_on_the_live_hosts_own_meminfo() {
        let mut live = crate::terminal_observe::parse_meminfo(
            "MemTotal: 15473336 kB\nMemAvailable: 6976900 kB\n\
             SwapTotal: 16776512 kB\nSwapFree: 4691496 kB\n",
        );
        live.psi_some_avg60_bp = Some(6);
        assert!(live.swap_pressured(), "swap history is deep on this host");
        // The argument both policy functions are handed. This is the defect: it
        // was `swap_pressured()` (true here) and must be `reclaim_pressured()`.
        assert!(
            !live.reclaim_pressured(),
            "45% of RAM available and 0.06% stall time is not reclaim pressure"
        );
        // Under glass with no real pressure: SOFT stash — stay attached, so
        // switch-back is instant and the page is not destroyed.
        assert!(!web_surface_background_detach(
            true,
            live.reclaim_pressured()
        ));
        // ⭐ AND ON THIS SAME READING THE PAGE IS NOT DESTROYED EITHER.
        //
        // 45% headroom is COMFORTABLE, so a surface the user configured no hold
        // for gets no destroy clock at all. This is the fixture that makes the
        // 2026-08-01 finding a regression test rather than a story: the live
        // host was reading almost exactly this while 134 of 182 recorded
        // destroys fired anyway, `reclaim_pressured: false`, and the user
        // reopened 109 of the 132 pages killed.
        assert_eq!(
            live.reclaim_posture(),
            crate::terminal_observe::ReclaimPosture::Comfortable
        );
        assert_eq!(
            web_surface_background_hold_ms_for(None, live.reclaim_posture(), 0),
            None,
            "a ten-minute clock on a host with 45% of its RAM free destroys \
             pages to buy memory nobody is asking for"
        );
        // The five-second window is still what genuine pressure selects.
        assert_eq!(
            web_surface_background_hold_ms_for(
                None,
                crate::terminal_observe::ReclaimPosture::Pressured,
                0
            ),
            Some(WEB_SURFACE_PRESSURED_BACKGROUND_HOLD_MS),
            "the five-second window is what the wrong argument used to select"
        );
    }

    #[test]
    fn under_glass_paint_holes_css_builds_evenodd_path_and_clears_when_empty() {
        assert_eq!(under_glass_paint_holes_css(&[]), None);
        // Degenerate rects are dropped (same as the input region); an
        // all-degenerate set means FULL paint, not a stale hole.
        assert_eq!(
            under_glass_paint_holes_css(&[(5, 5, 0, 10), (5, 5, 10, -1)]),
            None
        );
        // F.1 molded frame: each hole is a ROUNDED rect (radius 10, clamped
        // to half the short side) so the app-bg layer paints the corner
        // wedges over the page — the frame cuts the page's square corners.
        let path = under_glass_paint_holes_css(&[(100, 40, 800, 600), (10, 10, 20, 20)]).unwrap();
        assert_eq!(
            path,
            "path(evenodd, \"M0 0H32767V32767H0Z\
             M110 40h780a10 10 0 0 1 10 10v580a10 10 0 0 1 -10 10h-780a10 10 0 0 1 -10 -10v-580a10 10 0 0 1 10 -10Z\
             M20 10h0a10 10 0 0 1 10 10v0a10 10 0 0 1 -10 10h-0a10 10 0 0 1 -10 -10v-0a10 10 0 0 1 10 -10Z\")"
        );
        // The radius clamps to the short side, never inverting the geometry.
        let tiny = under_glass_paint_holes_css(&[(0, 0, 8, 30)]).unwrap();
        assert_eq!(
            tiny,
            "path(evenodd, \"M0 0H32767V32767H0Z\
             M4 0h0a4 4 0 0 1 4 4v22a4 4 0 0 1 -4 4h-0a4 4 0 0 1 -4 -4v-22a4 4 0 0 1 4 -4Z\")"
        );
    }

    #[test]
    fn app_background_layer_paint_matches_shell_frame_paint() {
        // The layer replicates the frame's background so legacy stacking is
        // pixel-identical and under glass swaps owners invisibly. One shared
        // computation backs both; this pins the rendered declarations too.
        let light = palette(UiTheme::ZedLight);
        let first_decl = |style: &str, prop: &str| -> String {
            style
                .split(&format!("{prop}:"))
                .nth(1)
                .and_then(|tail| tail.split(';').next())
                .unwrap_or_default()
                .to_string()
        };
        for (maximized, transparent_window) in
            [(false, false), (true, false), (false, true), (true, true)]
        {
            let frame = shell_style(
                light,
                10,
                "rgb(243, 247, 250)",
                "rgb(243, 247, 250)",
                light.gradient,
                "100% 100vh",
                "no-repeat",
                22.0,
                maximized,
                transparent_window,
            );
            let layer = shell_background_layer_style(
                light,
                10,
                "rgb(243, 247, 250)",
                "rgb(243, 247, 250)",
                light.gradient,
                "100% 100vh",
                "no-repeat",
                maximized,
                transparent_window,
            );
            for prop in [
                "background-color",
                "background-image",
                "background-size",
                "background-repeat",
            ] {
                assert_eq!(
                    first_decl(&frame, prop),
                    first_decl(&layer, prop),
                    "{prop} diverged (maximized={maximized}, transparent={transparent_window})"
                );
            }
            assert!(layer.contains("z-index:-1"));
            assert!(layer.contains("pointer-events:none"));
        }
    }

