    // XTERM-BUG: remote-cc-replay-codex-only — the GUI replay idempotency check
    // must recognize the Claude Code caret (U+276F ❯) and idle footer, not only
    // the Codex caret (U+203A ›). Otherwise a correctly-replayed Claude buffer is
    // judged not-visible, completion never fires, and the 100ms retry loop
    // reset+rewrites the buffer every tick (flash/churn) until the deadline.
    // Synthetic Claude prompt surface only — no session data.
    #[test]
    fn retained_replay_script_recognizes_claude_caret_not_only_codex() {
        let script = terminal_replay_retained_data_script_for_session(
            "remote-session://dev/claude",
            "\x1b[2J\x1b[H❯ Try \"edit <file>\"\r\n? for shortcuts\r\n",
            "daemon_retained_snapshot",
            0,
        );
        // promptNeedle is derived from EITHER caret (the later occurrence).
        assert!(
            script.contains("const claudePromptIx = strippedReplayText.lastIndexOf(\"❯\");"),
            "promptNeedle must consider the Claude caret U+276F"
        );
        assert!(
            script.contains("const promptIx = Math.max(codexPromptIx, claudePromptIx);"),
            "promptIx must take the later of the Codex/Claude carets"
        );
        // replayVisibleInEntry recognizes the Claude caret AND the idle footer…
        assert!(
            script.contains("visibleText.includes(\"›\") || visibleText.includes(\"❯\")"),
            "a settled replay must be recognized by the Claude caret, not only the Codex caret"
        );
        assert!(
            script.contains("visibleText.toLowerCase().includes(\"? for shortcuts\")"),
            "Claude's idle footer must count as a settled, visible replay"
        );
        // …and Codex caret recognition is preserved (no regression for Codex).
        assert!(script.contains("visibleText.includes(\"›\")"));
    }
    // Sum-total run #3 (#2 cold-re-resume vacuum, redesigned): the retained-replay
    // builder must carry the spawn-id-gated vacuum guard. The guard arms ONLY when
    // the payload's runtime spawn id differs from the one the entry was seeded
    // from (a true cold re-resume) AND the richer-client ratio fires — mirroring
    // terminal_retained_replay_policy::retained_replay_would_vacuum_richer_client.
    // A same-spawn or unknown-spawn (0) payload must never guard: the reverted
    // 2.8.64 blanket ratio gated every normal codex reveal into a shadow.
    #[test]
    fn retained_replay_vacuum_guard_is_spawn_id_gated() {
        let with_spawn = terminal_replay_retained_data_script_for_session(
            "remote-session://dev/codex",
            "OpenAI Codex\r\n› prompt\r\n",
            "daemon_screen_snapshot",
            1781000000000123,
        );
        assert!(
            with_spawn.contains("const runtimeSpawnId = 1781000000000123;"),
            "the daemon-reported spawn id must reach the replay script"
        );
        assert!(
            with_spawn.contains("const coldReResume = runtimeSpawnId > 0")
                && with_spawn.contains("&& runtimeSpawnId !== knownSpawnId;"),
            "the guard must require a DIFFERENT runtime spawn (cold re-resume), never magnitude alone"
        );
        assert!(
            with_spawn.contains("if (curBaseY >= 6 && incomingLines * 3 < curBaseY) {"),
            "the richer-client ratio must mirror retained_replay_would_vacuum_richer_client"
        );
        assert!(
            with_spawn.contains("entry.lastRetainedReplayVacuumGuardSkipped = true;"),
            "a guard skip must be observable on the entry"
        );
        assert!(
            with_spawn.contains("entry.lastSeededRuntimeSpawnId = runtimeSpawnId;"),
            "an applied payload must record its spawn id as the comparison anchor"
        );
        // The user/agent reconcile and any path without a spawn id pass 0 — the
        // script must carry the disarmed value so coldReResume can never be true.
        let without_spawn = terminal_replay_retained_data_script_for_session(
            "remote-session://dev/codex",
            "OpenAI Codex\r\n› prompt\r\n",
            "daemon_screen_snapshot",
            0,
        );
        assert!(
            without_spawn.contains("const runtimeSpawnId = 0;"),
            "spawn id 0 must keep the guard disarmed (fails open)"
        );
    }

    // XTERM-BUG: blank-viewport-client-snapshot-poison — on a cursor-addressed
    // (codex) collapsed-scrollback reveal, the replay must reconcile from the
    // daemon's authoritative SCREEN frame BEFORE falling back to the cached
    // client snapshot (which can be a sparse/poison frame the <=1 guard misses,
    // leaving the viewport clipped/blank and never promoting the daemon frame —
    // the live "switch-back broken paint / restart session" symptom).
    #[test]
    fn retained_replay_reconciles_from_daemon_screen_before_client_snapshot() {
        let script = terminal_replay_retained_data_script_for_session(
            "remote-session://dev/codex",
            "\x1b[2J\x1b[Hline 1\r\nline 2\r\n",
            "daemon_screen_snapshot",
            0,
        );
        assert!(
            script.contains("const daemonScreenSnapshotAuthoritative ="),
            "must recognize an authoritative daemon screen frame"
        );
        assert!(
            script.contains("replaySource === 'daemon_screen_snapshot'")
                && script.contains("replaySource === 'daemon_retained_history_screen_snapshot'"),
            "daemon screen + retained-history screen snapshots are authoritative"
        );
        assert!(
            script.contains(
                "if (daemonScreenSnapshotAuthoritative && writePayloadIntoEntry(entry, data))"
            ),
            "must write the daemon frame when authoritative"
        );
        assert!(
            script.contains(
                "followPromptForEntry(entry, 'retained_replay_reconcile_from_daemon_screen')"
            ),
            "reconcile path must follow the prompt and be observable"
        );
        // The daemon reconcile must be attempted BEFORE the client-snapshot fallback.
        let reconcile_ix = script
            .find("daemonScreenSnapshotAuthoritative && writePayloadIntoEntry")
            .expect("reconcile branch present");
        let snapshot_ix = script
            .find("snapshot && replaySessionSnapshotIntoEntry(entry, snapshot)")
            .expect("client-snapshot fallback present");
        assert!(
            reconcile_ix < snapshot_ix,
            "daemon screen reconcile must be attempted before the client-snapshot fallback"
        );
    }
