    #[test]
    fn edit5_no_saved_offset_mover_survives_while_following() {
        // EDIT-5 invariant (audit-viewport-scroll-control-flow, the 2.8.44
        // oscillation trap): no code path may move the viewport to a SAVED
        // offset while scroll intent is Following. The three historical
        // movers and their guards:
        //  1. persisted localStorage restore — must abandon unless the
        //     session is armed UserScrollback (f4eed1a).
        //  2. teardown snapshot restore — must not move the viewport to the
        //     snapshot offset at all (run #9 A.b.1: always follows).
        //  3. a stranded Following viewport is re-asserted by the
        //     settle-follow watchdog, the follow-once executor.
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        // Guard 1: the persisted-restore applier bails when follow engaged.
        assert!(script.contains("if (scrollbackIntent !== 'UserScrollback') {"));
        assert!(script.contains("persistedScrollRestoreAbandonedReason"));
        // Guard 2: the snapshot restore path has no offset mover left.
        assert!(
            !script.contains("forceXtermViewportY(targetViewportY, 'xterm_session_snapshot_restore')"),
            "teardown snapshot restore must not re-apply a saved viewport offset"
        );
        assert!(script.contains("scrollLiveCursorIntoView(false, 'xterm_session_snapshot_restore');"));
        // Guard 3: the follow-once executor exists and is intent-gated.
        assert!(script.contains("settle_follow_reassert"));
        assert!(script.contains("if (scrollbackIntent !== 'PromptFollow') { return; }"));
    }

    #[test]
    fn xterm_snapshot_restore_never_latches_user_scrollback_intent() {
        // Regression lock for the phantom-scrollback-latch fix (A.b.1,
        // run #8): the teardown snapshot carries the dying host's intent
        // for telemetry only — restoring it must start Following per the
        // scroll_mode spec, never re-assert UserScrollback+locked (which
        // made one spurious programmatic flip self-perpetuate across
        // remounts).
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        assert!(
            !script.contains("setScrollbackIntent('UserScrollback', `xterm_session_snapshot:"),
            "snapshot restore must not latch UserScrollback from a teardown snapshot"
        );
        assert!(script.contains("xterm_session_snapshot_intent_latch_dropped"));
        assert!(script.contains("setScrollbackIntent('PromptFollow', `xterm_session_snapshot:"));
    }

    #[test]
    fn terminal_eval_script_guards_against_blank_viewport_snapshot_poison() {
        // Regression lock for the blank-viewport-client-snapshot-poison fix
        // (see finding-blank-viewport-client-snapshot-poison). The capture path
        // must track a per-session nonblank max and refuse to overwrite a good
        // cached frame with a collapsed (<=1 nonblank line) one; the restore and
        // replay paths must reject such a collapsed frame so the daemon
        // authoritative content wins.
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        // Capture-side: nonblank-max tracking + collapsed-frame skip.
        assert!(script.contains(
            "window.__yggtermXtermSessionNonblankMax = window.__yggtermXtermSessionNonblankMax || {};"
        ));
        assert!(script.contains("const collapsedPoisonFrame = nonblankLineCount <= 1 && priorNonblankMax >= 6;"));
        assert!(
            script.contains("window.__yggtermXtermSessionNonblankMax[sessionPath] = Math.max("),
            "capture must record the per-session nonblank max"
        );
        // Restore-side guard helper (bootstrap script copy).
        assert!(script.contains(
            "const xtermSessionSnapshotIsCollapsedPoison = (sessionPath, nonblankLineCount) => {"
        ));
        assert!(script.contains("return Number(nonblankLineCount) <= 1 && priorMax >= 6;"));
        assert!(script.contains("if (xtermSessionSnapshotIsCollapsedPoison(sessionPath, nonblankLineCount)) {"));
    }

