    #[test]
    fn terminal_eval_script_rebinds_replaced_host_nodes_before_repaint() {
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        assert!(
            script.contains("const rebindCurrentHost = (reason, reopen) => {"),
            "runtime bridge should define a host rebind helper"
        );
        assert!(
            script.contains("const liveHost = document.getElementById(hostId);"),
            "rebind helper should resolve the current live host node by id"
        );
        assert!(
            script.contains(
                "const termElementDisconnected = Boolean(termElement && !termElement.isConnected);"
            ),
            "rebind helper should detect detached xterm roots on the current host"
        );
        assert!(
            script.contains("const termElementHost = termElement && termElement.closest"),
            "rebind helper should resolve the detached xterm element owner host"
        );
        assert!(
            script.contains("term_element_host=${termElementHost"),
            "the owner host must reach the trace — it is diagnostics, not a decision"
        );
        // The decision is now two-stage: the raw condition (`sameHostRepairWanted`)
        // and the post-circuit-breaker verdict (`sameHostNeedsReopen`). Both must
        // exist — the condition is what detects the fault, the verdict is what
        // bounds the retry.
        assert!(
            script.contains("const sameHostRepairWanted ="),
            "rebind helper should reopen the same host when the xterm DOM detached"
        );
        assert!(
            script.contains("let sameHostNeedsReopen = sameHostRepairWanted;"),
            "the reopen verdict must derive from the condition, through the breaker"
        );
        assert!(
            script.contains("|| (termElementDisconnected && !liveHost.querySelector('.xterm'))"),
            "same-host reopen should not clear an already-mounted xterm root just because term.element went stale"
        );
        assert!(
            script.contains("targetHost.appendChild(existing);"),
            "the surface owner must MOVE the existing xterm element back — term.open() \
             early-returns once term.element exists and would rebuild nothing"
        );
        assert!(
            script.contains("const terminalRendererSurfaceState = () => {"),
            "runtime bridge should classify missing xterm renderer surface layers"
        );
        assert!(
            script.contains("const repairMissingRendererSurface = (reason = '') => {"),
            "runtime bridge should expose a bounded xterm-native renderer surface repair"
        );
        assert!(
            script.contains("host_missing_renderable_layer=${hostMissingRenderableLayer}"),
            "rebind trace should report missing text/canvas renderer layers"
        );
        assert!(
            script.contains("message: `rebind_host host=${hostId} reason=${reason}"),
            "rebind helper should trace when the mounted host changes"
        );
        let request_visible_ix = script
            .find("const requestVisiblePaint = (forceFullRefresh = false) => {")
            .expect("requestVisiblePaint declaration present");
        let rebind_ix = script[request_visible_ix..]
            .find("rebindCurrentHost('request_visible_paint', true);")
            .expect("requestVisiblePaint should rebind to the current host before repaint");
        let input_hot_ix = script[request_visible_ix..]
            .find("const inputHot = terminalInputHot();")
            .expect("requestVisiblePaint should inspect input-hot state before paint work");
        assert!(rebind_ix < input_hot_ix);
    }

