    #[test]
    fn terminal_eval_script_restores_the_surface_after_every_host_wipe() {
        // `open()` in the bundled xterm.js (assets/xterm/xterm.js) early-returns as
        // soon as `term.element` exists, WITHOUT re-parenting it. So the old
        // "wipe the host, then term.open() to rebuild it" recovery rebuilt nothing
        // and stranded the terminal outside the DOM — a permanently blank viewport.
        // Every wipe must be followed by the one owner that MOVES the element back.
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        assert!(
            script.contains("const attachTerminalSurfaceToHost = (targetHost, site, allowOpen) => {"),
            "restoring the surface into a host must have exactly one owner"
        );
        for call in [
            "attachTerminalSurfaceToHost(host, 'rebind_host_attach', reopen)",
            "attachTerminalSurfaceToHost(host, 'rebuild_blank_host_attach', true)",
        ] {
            assert!(
                script.contains(call),
                "every recovery must restore through the one owner: {call}"
            );
        }
        for (wipe_site, restore_site) in [
            ("site: 'rebind_host_wipe'", "'rebind_host_attach'"),
            ("site: 'rebuild_blank_host_wipe'", "'rebuild_blank_host_attach'"),
        ] {
            let wipe = script.find(wipe_site).expect("wipe breadcrumb present");
            let restore = script.find(restore_site).expect("restore present");
            assert!(
                wipe < restore,
                "the restore for {wipe_site} must follow its wipe in the same task"
            );
        }
        assert_eq!(
            script.matches("term.open(host);").count(),
            1,
            "`term.open(host);` may appear exactly once — the mount, where term.element \
             does not exist yet. A second one is a no-op rebuild of a wiped host."
        );
        // `term.open(targetHost);` appears twice — the rebuild, then the retry after
        // the guard is disarmed — but BOTH must live inside attachTerminalSurfaceToHost.
        // Assert the ownership directly rather than a count, which only ever stood in
        // for it and would forbid a legitimate second attempt by the same owner.
        let owner_start = script
            .find("const attachTerminalSurfaceToHost = (targetHost, site, allowOpen) => {")
            .expect("the surface owner is present");
        let owner_end = script
            .find("const rebindCurrentHost = (reason, reopen) => {")
            .expect("the owner's body ends before rebindCurrentHost");
        assert!(owner_start < owner_end, "the owner precedes rebindCurrentHost");
        let opens: Vec<usize> = script
            .match_indices("term.open(targetHost);")
            .map(|(at, _)| at)
            .collect();
        assert_eq!(
            opens.len(),
            2,
            "exactly two opens: the rebuild, and the retry once the early-return \
             guard has been disarmed"
        );
        for at in opens {
            assert!(
                at > owner_start && at < owner_end,
                "`term.open(targetHost);` belongs to attachTerminalSurfaceToHost alone"
            );
        }
    }

    #[test]
    fn terminal_eval_script_rebuilds_a_husk_instead_of_moving_it() {
        // The husk is born in a PArecordsAL `term.open`: the bundle appends the bare
        // `.xterm` root to the host first and the screen fragment last, so a throw
        // in between leaves a connected, empty root that every placement guard
        // reads as healthy. Proven against the shipped bundle in
        // tools/xterm-harness/husk_is_born_in_a_partial_open.test.js.
        //
        // Two things must stay true or the husk becomes permanent again:
        //   1. the mount must notice an incomplete open and retry it, and
        //   2. the surface owner must never MOVE a husk and call that a repair.
        // Both repairs have to drop the husk root BEFORE opening, or the retry
        // strands it as an orphan beside the new root.
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        assert!(
            script.contains("const terminalSurfaceIsComplete = (root) =>"),
            "\"is this a real surface or a husk?\" must have exactly one owner"
        );
        assert!(
            script.contains("const existingIsHusk = Boolean(existing) && !terminalSurfaceIsComplete(existing);"),
            "the surface owner must classify term.element before trusting it"
        );
        assert!(
            script.contains("if (existing && !existingIsHusk) {"),
            "only a COMPLETE surface may be restored by moving it back"
        );
        assert!(
            script.contains("mode = existingIsHusk ? 'rebuilt_from_husk' : 'opened';"),
            "a husk must be rebuilt through open(), not reattached"
        );
        assert!(
            script.contains("mode = 'rebuild_from_husk_failed';"),
            "a rebuild that did not take must be reported, not assumed"
        );
        // A no-op open() means the early-return guard is armed over a terminal that
        // never finished opening (the guard is assigned mid-open, six services before
        // the screen reaches the root — see
        // tools/xterm-harness/husk_species_b_is_a_late_partial_open.test.js). Clearing
        // `element` disarms it so the retry can actually build the surface.
        for fragment in [
            "const disarmTarget = term && term._core && term._core.element",
            "disarmTarget.element = undefined;",
            "mode = 'rebuilt_from_husk_disarmed';",
        ] {
            assert!(
                script.contains(fragment),
                "a husk whose guard is armed must be repaired by disarming it, not \
                 abandoned to a remount; missing: {fragment}"
            );
        }
        assert!(
            script.contains("term && term._core && term._core.element"),
            "the private core shape must be feature-detected, so an xterm bump \
             degrades to putting the husk back rather than half-repairing silently"
        );
        let disarm_at = script
            .find("disarmTarget.element = undefined;")
            .expect("the disarm is present");
        let failure_report = script
            .find("mode = 'rebuild_from_husk_failed';")
            .expect("the give-up report is present");
        assert!(
            disarm_at < failure_report,
            "reporting the failure before attempting the disarm would make the \
             repair unreachable"
        );
        // Ordering: the husk has to leave the DOM before the open that replaces it.
        let husk_removed = script
            .find("if (existingIsHusk) {\n                    try {\n                        existing.remove();")
            .expect("the husk is dropped before the rebuild");
        let rebuild_open = script
            .find("term.open(targetHost);")
            .expect("the rebuild open is present");
        assert!(
            husk_removed < rebuild_open,
            "dropping the husk AFTER the open would strand it as an orphan root"
        );
        // The mount half: notice an incomplete open, discard, retry, and say so.
        for fragment in [
            "let mountOpenError = openTerminalSurfaceAtMount();",
            "if (!terminalSurfaceIsComplete(term && term.element ? term.element : null)) {",
            "discardHuskTerminalRoots(host, 'mount_partial_open_discard');",
            "terminal_mount_open_incomplete host=",
        ] {
            assert!(
                script.contains(fragment),
                "the mount must repair a partial open and report it: {fragment}"
            );
        }
        let mount_discard = script
            .find("discardHuskTerminalRoots(host, 'mount_partial_open_discard');")
            .expect("mount discard present");
        let mount_retry = script
            .find("const retryError = openTerminalSurfaceAtMount();")
            .expect("mount retry present");
        assert!(
            mount_discard < mount_retry,
            "the mount must discard the husk before retrying the open"
        );
    }

    #[test]
    fn terminal_eval_script_names_the_orphan_root_that_poisons_a_host() {
        // Knowing an orphan `.xterm` root exists was never enough to fix the husk.
        // `.xterm` roots have one manufacturer (`term.open`), so an orphan belongs
        // to some other closure; the autopsy has to be able to name that owner.
        let theme = terminal_theme(UiTheme::ZedLight, palette(UiTheme::ZedLight), 13.0, "");
        let script = terminal_eval_script("yggterm-terminal-test", &theme, true);
        assert!(
            script.contains("orphan_root_desc:"),
            "the husk signature must carry a description of the squatting root"
        );
        assert!(
            script.contains("entry.termElementRef = term && term.element ? term.element : null;"),
            "each host entry must publish its element so a sibling can name it as owner"
        );
        assert!(
            script.contains("reg[key].termElementRef === root"),
            "orphan forensics must resolve the owner through the published element"
        );
        for field in ["orphan_desc=", "host_id_elements=", "host_kids="] {
            assert!(
                script.contains(field),
                "the detach event must carry the forensic field {field}"
            );
        }
    }

