    #[test]
    fn terminal_eval_script_wires_glyph_gap_rows_detector() {
        // XTERM-BUG: blank-rendering-region — a blank band / dropped glyphs
        // inside an otherwise painted viewport is invisible to the aggregate
        // ink sample (other rows keep it nonzero). The per-row detector
        // compares buffer text rows against text-layer ink bands, traces a
        // glyph_gap_rows render anomaly, and heals with a targeted atlas
        // clear + row-range refresh, latched so it can never loop.
        let theme = terminal_theme(UiTheme::ZedDark, palette(UiTheme::ZedDark), 13.0, "");
        let script = terminal_eval_script_with_canvas_renderer(
            "yggterm-terminal-test",
            &theme,
            true,
            true,
            "test_reason",
            false,
            ("\x1b[A", "\x1b[B", 0),
        None);
        assert!(script.contains("pattern: 'glyph_gap_rows'"));
        assert!(
            script.contains("detectAndHealGlyphGapRows(reason)"),
            "the render-health pass must run the per-row scan when the aggregate sample is healthy"
        );
        assert!(
            script.contains("now - lastGlyphGapScanAtMs < 5000"),
            "the per-row scan must stay throttled — it does a full-canvas readback"
        );
        assert!(
            script.contains("now - lastGlyphGapHealAtMs > 10000"),
            "the glyph-gap heal must be latched so its own refresh cannot loop"
        );
        assert!(
            script.contains("renderHealthRecoveryBackoffMs * 2"),
            "render-health recovery must escalate its cooldown when a heal does not stick"
        );
    }

    /// The shipped xterm registers ONLY Unicode v6, where every
    /// Emoji_Presentation character is one cell wide — while every modern agent
    /// CLI writes it as two. Measured on the vendored bundle 2026-08-11:
    /// `wcwidth(U+2B50 ⭐) = 1`. From the first emoji on a line the CLI and the
    /// renderer disagree about where every later cell is, and a partial repaint
    /// strands the old glyph in the orphaned column — the owner's "weird
    /// characters appearing here and there".
    ///
    /// Behaviour is guarded against the REAL bundle in
    /// `tools/xterm-harness/emoji_cell_width.test.js`. This only guards that the
    /// app still installs the provider, and installs it on BOTH accessors: the
    /// renderer reads `charProperties`, so overriding `wcwidth` alone would fix
    /// nothing while looking correct.
    #[test]
    fn terminal_eval_script_widens_emoji_to_two_cells() {
        let theme = terminal_theme(UiTheme::ZedDark, palette(UiTheme::ZedDark), 13.0, "");
        let script = terminal_eval_script_with_canvas_renderer(
            "yggterm-terminal-test",
            &theme,
            true,
            true,
            "test_reason",
            false,
            ("\x1b[A", "\x1b[B", 0),
        None);
        assert!(
            script.contains("term.unicode.activeVersion = '11';"),
            "the terminal must activate the corrected width table"
        );
        assert!(
            script.contains("wcwidth: (cp) => (isWideEmoji(cp) ? 2 : uniBase.wcwidth(cp))"),
            "wcwidth must widen the Emoji_Presentation set and delegate the rest"
        );
        assert!(
            script.contains("charProperties: (cp, preceding) =>"),
            "charProperties must be overridden too — the RENDERER reads it, so a \
             wcwidth-only override paints the old widths and fixes nothing"
        );
        assert!(
            script.contains("uniSvc._providers && uniSvc._providers['6']"),
            "the provider must delegate to the bundle's own v6 table rather than \
             substituting a second full width table that can drift from it"
        );
        // ⭐ and ⛔ are the two the owner actually saw break; ⚠ is the control —
        // it is text-presentation, it rendered correctly in his frames, and
        // widening it would create the same bug in the opposite direction.
        assert!(
            script.contains("0x2B50,0x2B50") && script.contains("0x26D4,0x26D4"),
            "the two characters from the owner's frames must be in the wide set"
        );
        assert!(
            !script.contains("0x26A0,0x26A0"),
            "U+26A0 ⚠ is text-presentation and must stay ONE cell"
        );
    }

    #[test]
    fn terminal_eval_script_wires_stale_atlas_paint_detector() {
        // XTERM-BUG: webgl-stale-atlas-garble — glyph corruption (wrong-glyph
        // paint against an atlas that went stale during a rAF-throttle gap) is
        // invisible to ink sampling, so telemetry must detect the risk condition
        // itself: a render right after a >1s rAF gap with no atlas clear since
        // the gap began. The detector traces a stale_atlas_paint render anomaly
        // and heals with a targeted atlas clear, latched per gap episode.
        let theme = terminal_theme(UiTheme::ZedDark, palette(UiTheme::ZedDark), 13.0, "");
        let script = terminal_eval_script_with_canvas_renderer(
            "yggterm-terminal-test",
            &theme,
            true,
            true,
            "test_reason",
            false,
            ("\x1b[A", "\x1b[B", 0),
        None);
        assert!(script.contains("window.__yggtermRafGapMonitor"));
        assert!(script.contains("pattern: 'stale_atlas_paint'"));
        assert!(
            script.contains("lastAtlasClearAtMs = Date.now();"),
            "every atlas clear must stamp the timestamp the detector compares against"
        );
        assert!(
            script.contains(
                "rafGapMonitor.lastGapEndedAtMs !== rafGapMonitor.lastHealedGapEndedAtMs"
            ),
            "the stale-atlas heal must be latched per gap episode so its own refresh cannot loop"
        );
        // ⛔ The detector must NOT also require the render to land soon after the
        // gap. A stale atlas stays stale until something clears it, so the first
        // repaint after an occlusion garbles whether it lands in 600 ms or in a
        // minute — and "the agent wrote its next output a few seconds later" is
        // the shape the owner actually hits. The latch above, not a proximity
        // window, is what bounds the heal.
        assert!(
            !script.contains("staleAtlasNowMs - rafGapMonitor.lastGapEndedAtMs < 600"),
            "the stale-atlas detector must not re-introduce a proximity window that \
             blinds it to a late first repaint"
        );
        assert!(
            script.contains("render_lag_after_gap_ms:"),
            "the lag between the gap ending and the garbled render must be recorded, \
             since it is no longer a precondition"
        );
        // The intent and the outcome are separate records. `healed: true` used to
        // be a literal written before the heal was even armed, so the trace
        // reported 8 successful repairs while the owner watched garbled glyphs.
        assert!(
            !script.contains("healed: true"),
            "a heal that has not run yet must never claim it succeeded"
        );
        assert!(
            script.contains("heal_scheduled: true"),
            "the detection record states the INTENT to heal"
        );
        assert!(
            script.contains("pattern: 'stale_atlas_heal_outcome'"),
            "the heal must trace what it actually did, separately from deciding to do it"
        );
        // ⭐ The atlas must be cleared when the gap ENDS, not when a garbled
        // frame is caught. Detection can only ever fire after the bad frame has
        // been painted and seen; the owner's report was a viewport in which
        // every glyph was wrong, so painting one at all is the defect.
        let gap_tick = script
            .split("const rafGapTick = () => {")
            .nth(1)
            .and_then(|body| body.split("window.requestAnimationFrame(rafGapTick);").next())
            .expect("the rAF gap monitor tick should be present");
        assert!(
            gap_tick.contains("clearTextureAtlas"),
            "the gap monitor must clear every host's atlas the moment the throttle ends, \
             before any render can paint from it"
        );
        assert!(
            gap_tick.contains("gapEntry.lastAtlasClearAtMs = now;"),
            "the pre-emptive clear must stamp the same field the detector reads, or the \
             repair path fires again for work prevention already did"
        );
        // ⛔ AND IT MUST BE READABLE. Both counters existed in the page and were
        // surfaced in no instrument — not app state, not the trace, not
        // `server app web eval` (which lands in a web surface, where the monitor
        // is null). So "did the atlas defence run?" had no answer, and a repair
        // nobody can measure is the same defect as no repair at all. The counter
        // has to reach the HOST ENTRY, because that is the only thing the health
        // report reads.
        assert!(
            gap_tick.contains("gapEntry.preemptiveAtlasClearCount"),
            "the pre-emptive clear must count itself on the host entry, or no instrument \
             can ever say whether it ran"
        );
        // ⛔ AN UNNECESSARY ATLAS CLEAR IS NOT A HARMLESS ONE. Wiping the atlas
        // re-rasterizes every glyph, and cells painted before their glyph lands
        // come out BLANK — that is the eaten-digits / holed-highlight symptom
        // 3.0.106 caused. So a host that mounted AFTER the throttle, whose atlas
        // was therefore built fresh, must be left alone.
        assert!(
            gap_tick.contains("if (Number(gapEntry.mountedAtMs || 0) >= now - gap) continue;"),
            "the pre-emptive clear must skip hosts that mounted after the gap — their \
             atlas cannot be stale and wiping it paints blank cells"
        );
        assert!(
            script.contains("mountedAtMs: Date.now(),"),
            "the host entry must record when its atlas came into existence"
        );
        assert!(
            script.contains("rafGapMonitor.lastHealedGapEndedAtMs"),
            "the heal latch must live on the PAGE-GLOBAL monitor: a per-host closure \
             variable resets on remount and re-arms an ancient gap forever"
        );
        assert!(
            script.contains("atlasClearedAtMs > 0 && atlasClearedAtMs < gapStartedAtMs"),
            "a never-cleared atlas (0) is the FRESHEST state, not the stalest — reading \
             0 as stale made every fresh mount heal itself in a loop"
        );
        for field in [
            "stale_atlas_heal_count:",
            "preemptive_atlas_clear_count:",
            "last_preemptive_atlas_clear_at_ms:",
        ] {
            assert!(
                script.contains(field),
                "the host health report must carry {field} — see docs/pending-bugs.md, \
                 this is the field whose absence left the owner's garbled-viewport \
                 report impossible to close either way"
            );
        }
    }

