    #[test]
    fn hidden_loading_dots_do_not_keep_css_animation_running() {
        let source = SHELL_SOURCE;
        let animated_dot_count = source
            .lines()
            .filter(|line| {
                line.contains("animation:yggterm-tree-loading-dot")
                    && !line.contains("source.matches(")
                    && !line.contains("line.contains(")
            })
            .count();
        let classed_dot_count = source.matches("class: \"yggterm-loading-dot\"").count();

        assert!(
            TREE_LOADING_DOT_CSS.contains("[style*=\"visibility:hidden\"] .yggterm-loading-dot")
        );
        assert!(
            TREE_LOADING_DOT_CSS.contains(".yggterm-loading-dot[style*=\"visibility:hidden\"]")
        );
        assert!(TREE_LOADING_DOT_CSS.contains("animation: none !important"));
        // The busy circle icon is retired — working is signalled by the
        // blinking status dot. Nothing should render the spinner class
        // anymore. (Needle built at runtime so this line doesn't self-match.)
        let spinner_class_needle = format!("class: \"{}\"", "yggterm-tree-spinner");
        assert!(!source.contains(&spinner_class_needle));
        // Build the search needle at runtime so this test's own source text
        // doesn't contain the literal needle and self-trigger the check.
        let spinner_animation_needle = format!("animation:{}", "yggterm-tree-spinner");
        let spinner_animation_line_count = source
            .lines()
            .filter(|line| line.contains(&spinner_animation_needle))
            .count();
        assert_eq!(spinner_animation_line_count, 0);
        assert!(TREE_SPINNER_CSS.contains("animation: none !important"));
        assert!(
            source.contains(
                "[data-yggterm-app-control-backgrounded=\\\"true\\\"] .yggterm-loading-dot"
            )
        );
        assert!(source.contains(
            "[data-yggterm-app-control-backgrounded=\\\"true\\\"] .yggterm-tree-spinner"
        ));
        assert!(
            source.contains("[data-yggterm-window-focused=\\\"false\\\"] .yggterm-loading-dot")
        );
        assert!(
            source.contains("[data-yggterm-window-focused=\\\"false\\\"] .yggterm-tree-spinner")
        );
        assert!(source.contains("\"data-yggterm-window-focused\": if window_focused"));
        assert_eq!(
            animated_dot_count, classed_dot_count,
            "every tree-loading-dot animation must carry the yggterm-loading-dot class so hidden retained UI cannot drive WebKit's animation clock"
        );
    }

