    // DESIGN.md "Status indicator vocabulary": green = keep-alive, blue =
    // non-keep-alive, blinking = working — one dot, two encodings.
    #[test]
    fn live_session_status_dot_encodes_keep_alive_color_and_working_blink() {
        let dark = palette(UiTheme::ZedDark);
        let kept_idle = live_session_status_dot_style(dark, true, false);
        assert!(kept_idle.contains("#22c55e"));
        let kept_working = live_session_status_dot_style(dark, true, true);
        assert!(kept_working.contains("#22c55e"));
        assert!(kept_working.contains("yggterm-status-dot-blink"));
        // HARD on/off blink (2026-06-26): the off half snaps the dot to a full
        // `opacity: 0` — no transition, no fade, no halo ring.
        assert!(STATUS_DOT_BLINK_CSS.contains("opacity: 0 !important;"));
        assert!(!STATUS_DOT_BLINK_CSS.contains("transition"));
        assert!(!STATUS_DOT_BLINK_CSS.contains("ease-in-out"));
        assert!(!kept_working.contains("box-shadow"));
        let transient_idle = live_session_status_dot_style(dark, false, false);
        assert!(transient_idle.contains("#3b82f6"));
        let transient_working = live_session_status_dot_style(dark, false, true);
        assert!(transient_working.contains("#3b82f6"));
        assert!(transient_working.contains("yggterm-status-dot-blink"));
        // The keep-alive helper stays the green/idle variant.
        assert_eq!(
            live_session_keep_alive_dot_style(dark),
            live_session_status_dot_style(dark, true, false)
        );
    }
    // ⛔ THE DEFECT CLASS THIS TEST EXISTS FOR: a blink phase that only the
    // STYLE system can see. The shipped design animated the inherited custom
    // property `--yggterm-status-dot-blink` from `@keyframes` on `:root`;
    // `getComputedStyle` read a perfect square wave off it while the pixels
    // never moved, because WebKitGTK does not mark a custom property's `var()`
    // consumers dirty for paint. So the rule is stated where it can be checked:
    // the stylesheet declares NO animation at all — the phase comes from a
    // timer whose class toggle is an ordinary style change, the kind the paint
    // path cannot ignore.
    //
    // The other half of the shape survives unchanged: exactly ONE clock, and no
    // dot owns a phase. N dots blinking at N phases cost N full-window blits per
    // cycle on a software-GL host; one shared phase costs one, no matter how
    // many dots blink.
    #[test]
    fn exactly_one_clock_drives_every_dot_and_it_is_one_the_paint_path_can_see() {
        let dark = palette(UiTheme::ZedDark);
        assert!(
            !STATUS_DOT_BLINK_CSS.contains("@keyframes"),
            "a keyframe animation of a custom property updates style and not \
             pixels — the phase must come from the clock: {STATUS_DOT_BLINK_CSS}"
        );
        assert!(
            !STATUS_DOT_BLINK_CSS.contains("animation:"),
            "no animation anywhere in the blink stylesheet: {STATUS_DOT_BLINK_CSS}"
        );
        // The rule and the clock agree on one class name, and the clock's
        // half-cycle and the documented period stay one fact.
        assert!(STATUS_DOT_BLINK_CSS.contains(&format!(":root.{STATUS_DOT_BLINK_OFF_CLASS} ")));
        assert!(STATUS_DOT_BLINK_CSS.contains(STATUS_DOT_BLINK_VAR));
        assert!(STATUS_DOT_BLINK_JS.contains(&format!("'{STATUS_DOT_BLINK_OFF_CLASS}'")));
        assert!(
            STATUS_DOT_BLINK_JS.contains(&format!(", {});", STATUS_DOT_BLINK_PERIOD_MS / 2)),
            "the clock ticks every half period: {STATUS_DOT_BLINK_JS}"
        );
        // Installing twice must not start a second clock — three surfaces emit
        // the rule and any of them may mount first.
        assert!(STATUS_DOT_BLINK_JS.contains("if (window.__yggtermBlinkClock)"));
        // Every dot style in the app carries the shared marker; none declares an
        // animation, so none can acquire a phase of its own.
        let dot_styles = [
            live_session_status_dot_style(dark, true, true),
            live_session_status_dot_style(dark, false, true),
            web_tab_activity_dot_style(true, false),
            status_dot_blink_opacity_css(true),
        ];
        for style in &dot_styles {
            assert!(
                style.contains("var(--yggterm-status-dot-blink, 1)"),
                "working dot must read the shared phase: {style}"
            );
            assert!(
                !style.contains("animation:"),
                "a dot must never own an animation: {style}"
            );
        }
    }
    // Dioxus applies `style` property-by-property and never clears a key a later
    // render drops, so working and idle MUST declare the same keys — otherwise a
    // session that stops working keeps the blink forever.
    #[test]
    fn status_dot_declares_the_same_style_keys_working_and_idle() {
        let dark = palette(UiTheme::ZedDark);
        let keys = |style: &str| {
            let mut keys: Vec<String> = style
                .split(';')
                .filter_map(|decl| decl.split(':').next())
                .map(|key| key.trim().to_string())
                .filter(|key| !key.is_empty())
                .collect();
            keys.sort();
            keys
        };
        assert_eq!(
            keys(&live_session_status_dot_style(dark, true, true)),
            keys(&live_session_status_dot_style(dark, true, false))
        );
        assert_eq!(
            keys(&web_tab_activity_dot_style(true, false)),
            keys(&web_tab_activity_dot_style(false, false))
        );
        assert!(status_dot_blink_opacity_css(false).contains("opacity: 1;"));
        assert!(!status_dot_blink_opacity_css(false).contains("var("));
    }

    // ========================================================================
    // A BACKGROUND TAB PLAYING MEDIA — the blinking indicator (owner mandate,
    // 2026-08-20). The falsifier is a live screenshot and no unit test can
    // stand in for it; what these lock is everything that would make the
    // screenshot lie.
    // ========================================================================

    /// ⛔ THE ONE RULE: the dot marks a BACKGROUND tab whose media claim is
    /// FRESH. Both halves have their own failure and each one is silent.
    #[test]
    fn only_a_background_tab_with_a_fresh_engine_answer_earns_the_media_dot() {
        let now = 1_000_000_u64;
        // The case the mandate exists for.
        assert!(web_tab_earns_media_dot(false, true, now, now));
        // FOREGROUND: the user is already looking at it.
        assert!(!web_tab_earns_media_dot(true, true, now, now));
        // Silent: the whole point. An indicator that blinks on a quiet row is
        // worse than none, because the user stops believing the ones that mean it.
        assert!(!web_tab_earns_media_dot(false, false, now, now));
        // A claim still inside the freshness window is still believed — this is
        // what lets an hour-long album keep its dot between heartbeats.
        assert!(web_tab_earns_media_dot(
            false,
            true,
            now - (WEB_SURFACE_MEDIA_MAX_MS - 1),
            now,
        ));
        // ...and one nobody has renewed has lapsed. The surface may have been
        // destroyed by a session close or replaced by a reload; from here those
        // are indistinguishable from real playback, which is why the window and
        // not a guess is the answer.
        assert!(!web_tab_earns_media_dot(
            false,
            true,
            now - (WEB_SURFACE_MEDIA_MAX_MS + 1),
            now,
        ));
        // A stamp from the future (clock step) must not read as ancient.
        assert!(web_tab_earns_media_dot(false, true, now + 5_000, now));
    }

    /// The heartbeat has to be comfortably inside the window it renews, or a
    /// genuinely playing tab flickers off between beats — the exact false
    /// negative that teaches the user to ignore the dot.
    #[test]
    fn the_media_heartbeat_renews_well_inside_the_window_it_renews() {
        assert!(
            WEB_SURFACE_MEDIA_HEARTBEAT_MS * 2 <= WEB_SURFACE_MEDIA_MAX_MS,
            "a renewal every {WEB_SURFACE_MEDIA_HEARTBEAT_MS}ms cannot keep a \
             {WEB_SURFACE_MEDIA_MAX_MS}ms claim alive across a slow tick",
        );
        // ...and far above the reconcile beat, or a playing tab writes shell
        // state sixty times a second and repaints the rail with it.
        assert!(WEB_SURFACE_MEDIA_HEARTBEAT_MS > WEB_SURFACE_RECONCILE_BEAT_MS * 10);
    }

    /// The media dot is the SAME dot, so it must obey the same two laws the
    /// loading light does: join the one blink clock, and declare the same style
    /// keys lit and unlit (Dioxus never clears a key a later render drops, so an
    /// arm that omitted one would leave a finished tab blinking forever).
    #[test]
    fn the_media_dot_joins_the_one_clock_and_keeps_the_key_set_fixed() {
        let keys = |style: &str| {
            let mut keys: Vec<String> = style
                .split(';')
                .filter_map(|decl| decl.split(':').next())
                .map(|key| key.trim().to_string())
                .filter(|key| !key.is_empty())
                .collect();
            keys.sort();
            keys
        };
        let media = web_tab_activity_dot_style(false, true);
        assert!(
            media.contains("var(--yggterm-status-dot-blink, 1)"),
            "the media dot must read the shared phase, never its own: {media}"
        );
        assert!(
            !media.contains("animation:"),
            "a dot must never own an animation: {media}"
        );
        assert!(media.contains("#22c55e"), "a lit dot is the vocabulary's green");
        assert_eq!(keys(&media), keys(&web_tab_activity_dot_style(false, false)));
        // Either cause lights it, and a tab that is both loading AND playing is
        // lit once, not twice.
        assert_eq!(web_tab_activity_dot_style(true, false), media);
        assert_eq!(web_tab_activity_dot_style(true, true), media);
        assert!(web_tab_activity_dot_style(false, false).contains("transparent"));
    }

    /// ⛔ THE DUPLICATE LISTING, reported from a screenshot of a real launcher:
    /// the same two verbs offered twice in one menu.
    ///
    /// One manifest cannot cause it — its `name` must equal its own file stem,
    /// so one app is one file — which means the list reaching the menu builder
    /// already held the registration twice. The defence belongs where the list
    /// becomes a menu, because that is the one place that can be sure, whatever
    /// went wrong upstream.
    #[test]
    fn one_apps_verb_is_offered_once_however_often_it_is_registered() {
        let verb = |id: &str, label: &str, args: &[&str]| AppVerb {
            id: id.to_string(),
            label: label.to_string(),
            args: args.iter().map(|a| a.to_string()).collect(),
            ..Default::default()
        };
        let meter = AppManifest {
            name: "meter".into(),
            label: "Meter".into(),
            binary: "/opt/demo/meter".into(),
            verbs: vec![
                verb("open", "Cluster meter", &[]),
                verb("boot", "Cluster boot", &["--tab", "boot"]),
            ],
            ..Default::default()
        };
        // The reported shape: the same registration present twice.
        let entries = app_launcher_entries(&[meter.clone(), meter.clone()]);
        let labels: Vec<&str> = entries.iter().map(|(_, v)| v.label.as_str()).collect();
        assert_eq!(labels, vec!["Cluster meter", "Cluster boot"]);

        // ⚠ ...and the over-reach this must NOT have. Two DIFFERENT apps that
        // happen to share a binary are two real entries, and a key built on the
        // resolved command would silently delete one of them.
        let twin = AppManifest {
            name: "gauge".into(),
            label: "Gauge".into(),
            binary: "/opt/demo/meter".into(),
            verbs: vec![verb("open", "Gauge", &[])],
            ..Default::default()
        };
        assert_eq!(app_launcher_entries(&[meter, twin]).len(), 3);
    }

    /// A lit dot says WHY when hovered; an unlit one says nothing at all, so the
    /// rail is not full of rows announcing that they are idle.
    #[test]
    fn only_a_lit_activity_dot_carries_a_tooltip() {
        assert_eq!(web_tab_activity_dot_title(false, false), None);
        assert_eq!(web_tab_activity_dot_title(true, false), Some("Loading"));
        assert_eq!(
            web_tab_activity_dot_title(false, true),
            Some("Playing media in the background"),
        );
        // Loading is the transient of the two, so it is what a row that is both
        // reports while it lasts.
        assert_eq!(web_tab_activity_dot_title(true, true), Some("Loading"));
    }

    /// ⛔ BOTH CONSUMERS ASK THE SAME QUESTION, and they have to.
    ///
    /// Two things consult "is this surface playing": the background-activity dot
    /// and the reap veto that keeps a backgrounded surface alive. They were both
    /// asking about AUDIO, and both were therefore blind to a muted video —
    /// meaning a background tab playing a muted video showed no dot AND could be
    /// destroyed out from under the playback.
    ///
    /// Fixing one and not the other is the obvious next mistake, so this
    /// requires the audio-only spelling to be gone from the shell entirely.
    #[test]
    fn nothing_in_the_shell_still_asks_only_about_audio() {
        let source = SHELL_SOURCE;
        let product: Vec<&str> = yggterm_core::agent_cli::product_lines(&source)
            .into_iter()
            .map(|(_, line)| line)
            .collect();
        assert!(
            !product
                .iter()
                .any(|line| line.contains("fn nothing_in_the_shell_still_asks_only_about_audio")),
            "the scan is reading this test, so its own needle would satisfy it",
        );
        for spelling in ["web_surface_is_playing_audio", "is_playing_audio("] {
            assert!(
                !product.iter().any(|line| line.contains(spelling)),
                "the shell still asks about AUDIO ({spelling}) — a muted video answers false"
            );
        }
        // …and both consumers reach the media predicate.
        assert!(
            product
                .iter()
                .any(|line| line.contains("desktop.web_surface_is_playing_media(")),
            "the activity dot lost its probe"
        );
        assert!(
            product
                .iter()
                .any(|line| line.contains("media.is_playing_media(surface.native_id)")),
            "the reap veto lost its probe"
        );
    }

    /// ⛔⛔ THE DEFECT THAT WOULD BLIND THE WHOLE FEATURE, AND IT FAILS SILENTLY.
    ///
    /// The reconciler's page-state poll sits behind `if entry.stashed_at_ms
    /// .is_none()`, because a stashed surface's URL and title cannot change while
    /// nothing drives it. Media is the opposite case: a soft-stashed surface IS a
    /// background tab, which is the only thing this signal was ever asked for.
    /// Tucked under that guard — the natural place for a new engine poll, right
    /// beside the three that are already there — the probe would read silence
    /// from every tab it was built to find, and would do it in the reassuring
    /// direction: no dot anywhere, nothing visibly broken, a feature that simply
    /// never fires.
    ///
    /// ⚠ Locked on the SOURCE because there is nothing else to lock it on: the
    /// bug is a line's POSITION, and a probe in the wrong place computes a
    /// perfectly correct answer to a question about the wrong surface.
    #[test]
    fn the_media_probe_runs_outside_the_not_stashed_guard() {
        let source = SHELL_SOURCE;
        let product: Vec<&str> = yggterm_core::agent_cli::product_lines(&source)
            .into_iter()
            .map(|(_, line)| line)
            .collect();
        assert!(
            !product
                .iter()
                .any(|line| line.contains("fn the_media_probe_runs_outside_the_not_stashed_guard")),
            "the scan is reading this test, so its own needle would satisfy it",
        );
        let probe = product
            .iter()
            .position(|line| {
                line.contains("let media_playing = desktop.web_surface_is_playing_media(")
            })
            .expect(
                "the reconciler no longer probes the engine for media — the tab dot \
                 is now driven by something that is not the engine's own answer",
            );
        let guard = product
            .iter()
            .position(|line| line.trim() == "if entry.stashed_at_ms.is_none()")
            .expect("the not-stashed guard moved; re-read this test before editing it");
        assert!(
            probe < guard,
            "the media probe (line {probe} of the product scan) sits INSIDE the \
             not-stashed guard (line {guard}) — it will read silent on every \
             backgrounded tab, which is every tab this indicator exists for",
        );
    }
