    #[test]
    fn remote_preview_tail_hydration_is_readable_without_immediate_resync() {
        let mut session = test_live_shell_session("remote-session://dev/preview");
        session.source = SessionSource::LiveSsh;
        session.preview.blocks.push(SessionPreviewBlock {
            role: "ASSISTANT",
            timestamp: "2026-05-22".to_string(),
            tone: PreviewTone::Assistant,
            folded: false,
            lines: vec!["Recent assistant response".to_string()],
            kind: PreviewBlockKind::Message,
            activity: None,
        });
        session.metadata.push(SessionMetadataEntry {
            label: "Storage",
            value: "/home/user/.codex/sessions/example.jsonl".to_string(),
        });
        session.metadata.push(SessionMetadataEntry {
            label: "Preview Hydration",
            value: "tail".to_string(),
        });

        // ⚠ CONTRACT CHANGED 2026-08-03. This used to assert that ONE block
        // plus a `tail` marker needs no resync. That combination is now
        // distrusted on purpose: holding no more than
        // `LIVE_SNAPSHOT_PREVIEW_BLOCK_LIMIT` while claiming a full tail is the
        // fingerprint of a CAPPED payload wearing hydration's badge, and
        // trusting it froze a 670-block transcript at 2 blocks forever on the
        // live host. A delivered tail is one that carries more than the cap.
        for ix in 0..=yggterm_server::LIVE_SNAPSHOT_PREVIEW_BLOCK_LIMIT {
            session.preview.blocks.push(SessionPreviewBlock {
                role: "ASSISTANT",
                timestamp: format!("2026-05-22 delivered {ix}"),
                tone: PreviewTone::Assistant,
                folded: false,
                lines: vec![format!("delivered turn {ix}")],
                kind: PreviewBlockKind::Message,
                activity: None,
            });
        }
        assert!(!remote_preview_needs_refresh(&session));
        assert!(!remote_preview_should_auto_sync(&session));
    }
    #[test]
    fn remote_preview_tail_hydration_pins_chat_reader_to_latest_on_open() {
        let mut session = test_live_shell_session("remote-session://dev/preview");
        session.source = SessionSource::LiveSsh;
        session.preview.blocks.push(SessionPreviewBlock {
            role: "USER",
            timestamp: "2026-05-21".to_string(),
            tone: PreviewTone::User,
            folded: false,
            lines: vec!["older transcript head".to_string()],
            kind: PreviewBlockKind::Message,
            activity: None,
        });
        session.preview.blocks.push(SessionPreviewBlock {
            role: "ASSISTANT",
            timestamp: "2026-05-22".to_string(),
            tone: PreviewTone::Assistant,
            folded: false,
            lines: vec!["latest transcript tail".to_string()],
            kind: PreviewBlockKind::Message,
            activity: None,
        });
        session.metadata.push(SessionMetadataEntry {
            label: "Preview Hydration",
            value: "tail".to_string(),
        });

        assert!(preview_should_pin_latest_on_open(
            &session,
            WorkspaceViewMode::Rendered,
            PreviewLayoutMode::Chat,
            false,
        ));

        let (path, key) = preview_latest_pin_request(&session);
        assert_eq!(path, "remote-session://dev/preview");
        assert!(key.contains("tail"), "the key carries the hydration state");
        // ⚠ CONTRACT CHANGED 2026-08-03: the key deliberately does NOT carry
        // the last block's text any more. Including it made the key change
        // every time the transcript grew, so on a live session the pin re-armed
        // forever and the reader could never scroll up.
        assert!(
            !key.contains("latest transcript tail"),
            "content must not key the pin, or a growing session re-pins forever"
        );
        assert!(preview_latest_initial_scroll_top(&session) >= 0.0);
        for ix in 0..(PREVIEW_BLOCK_WINDOW + 3) {
            session.preview.blocks.push(SessionPreviewBlock {
                role: "ASSISTANT",
                timestamp: format!("2026-05-22 tail {ix}"),
                tone: PreviewTone::Assistant,
                folded: false,
                lines: vec![format!("latest transcript tail {ix}")],
                kind: PreviewBlockKind::Message,
                activity: None,
            });
        }
        // The hard-pinned "latest" window this used to assert over is GONE
        // (`preview_latest_materialized_window`, 11.23): it selected
        // `start = len - PREVIEW_BLOCK_WINDOW, end = len` and ignored scroll,
        // so no reader could reach an older turn. Nothing computed it any more
        // and the surface has been scroll-driven since. The pin is a scroll
        // POSITION, which is what the rest of this test checks.
        let mounted_anchor_scroll = preview_latest_anchor_scroll_options();
        assert!(matches!(
            mounted_anchor_scroll.behavior,
            ScrollBehavior::Instant
        ));
        assert!(matches!(
            mounted_anchor_scroll.vertical,
            ScrollLogicalPosition::End
        ));
        assert!(matches!(
            mounted_anchor_scroll.horizontal,
            ScrollLogicalPosition::Nearest
        ));

        let script = preview_scroll_to_latest_script(&path);
        assert!(script.contains("data-preview-scroll"));
        assert!(script.contains("scrollTop = target"));
        assert!(script.contains("maxAttempts = 80"));
        assert!(script.contains("data-preview-latest-anchor"));
        assert!(script.contains("remote-session://dev/preview"));
    }
    #[test]
    fn preview_latest_pin_respects_non_chat_search_and_unhydrated_modes() {
        let mut session = test_live_shell_session("remote-session://dev/preview");
        session.source = SessionSource::LiveSsh;
        session.preview.blocks.push(SessionPreviewBlock {
            role: "ASSISTANT",
            timestamp: "2026-05-22".to_string(),
            tone: PreviewTone::Assistant,
            folded: false,
            lines: vec!["latest transcript tail".to_string()],
            kind: PreviewBlockKind::Message,
            activity: None,
        });
        session.metadata.push(SessionMetadataEntry {
            label: "Preview Hydration",
            value: "tail".to_string(),
        });
        assert!(!preview_should_pin_latest_on_open(
            &session,
            WorkspaceViewMode::Terminal,
            PreviewLayoutMode::Chat,
            false,
        ));
        assert!(!preview_should_pin_latest_on_open(
            &session,
            WorkspaceViewMode::Rendered,
            PreviewLayoutMode::Graph,
            false,
        ));
        assert!(!preview_should_pin_latest_on_open(
            &session,
            WorkspaceViewMode::Rendered,
            PreviewLayoutMode::Chat,
            true,
        ));
        session
            .metadata
            .retain(|entry| entry.label != "Preview Hydration");
        session.metadata.push(SessionMetadataEntry {
            label: "Preview Hydration",
            value: "head".to_string(),
        });
        assert!(!preview_should_pin_latest_on_open(
            &session,
            WorkspaceViewMode::Rendered,
            PreviewLayoutMode::Chat,
            false,
        ));
    }
