    /// ⛔ INDENTATION IS BUDGETED (`DESIGN.md` §"Row sets"). Past two levels the
    /// indent holds and the head's own number carries the depth, because a title
    /// clipped to nothing is worse than a column that stops stepping.
    #[test]
    fn indentation_stops_stepping_once_the_sidebar_runs_out_of_room() {
        let rows = live_rows_for_seats(
            &[
                ("remote-session://dev/a", "6.0"),
                ("remote-session://dev/b", "6.1"),
                ("remote-session://dev/c", "6.1.1"),
                ("remote-session://dev/d", "6.1.1.1"),
                ("remote-session://dev/e", "6.1.1.1.1"),
            ],
            &HashSet::new(),
            &yggterm_core::row_set_outline::RowArrangement::default(),
        );
        let depths: Vec<usize> = rows.iter().map(|(_, depth)| *depth).collect();
        assert_eq!(
            depths,
            vec![1, 2, 3, 3, 3],
            "the fourth and fifth levels are still NESTED — they are drawn under \
             their head and hidden with it — they simply stop moving right"
        );
    }

    /// The head is the only row that gets a disclosure control, and it reports
    /// how many rows it holds. A split's compound row counts panes and must
    /// never offer to collapse them.
    #[test]
    fn only_a_head_is_drawn_with_a_disclosure_control() {
        let live_sessions: Vec<ManagedSessionView> = [
            ("remote-session://dev/orch", "6.0"),
            ("remote-session://dev/gate", "6.1"),
            ("remote-session://dev/gate-a", "6.1.1"),
        ]
        .iter()
        .map(|(path, seat)| seated_live_session(path, seat))
        .collect();
        let mut expanded = HashSet::new();
        expanded.insert("__live_sessions__".to_string());
        let rows = merged_sidebar_rows(&[], &[], &[], &live_sessions, &expanded);
        let head = rows
            .iter()
            .find(|row| row.full_path == "remote-session://dev/orch")
            .expect("head row");
        let leaf = rows
            .iter()
            .find(|row| row.full_path == "remote-session://dev/gate-a")
            .expect("leaf row");
        assert!(row_heads_a_row_set(head));
        assert_eq!(
            head.descendant_sessions, 3,
            "itself plus the two rows beneath it, however deep they sit"
        );
        assert!(!row_heads_a_row_set(leaf));
        assert_eq!(leaf.descendant_sessions, 1);
        let mut split_row = head.clone();
        split_row.full_path = "split://group-1".to_string();
        assert!(
            !row_heads_a_row_set(&split_row),
            "a split is a VIEW, not an arrangement — it counts its panes in the \
             same field and must not offer to collapse rows it does not hold"
        );
    }

    /// ⛔ THE CACHE MUST SEE THE SEAT. Reseating a row rearranges the sidebar,
    /// and the merge is memoized — before row sets the seat only reached the
    /// label, which is re-composed after the cache, so leaving it out of the key
    /// cost nothing and would now leave the outline drawn the old way.
    #[test]
    fn reseating_a_row_rebuilds_the_outline_rather_than_serving_the_cached_one() {
        let flat = live_rows_for_seats(
            &[
                ("remote-session://dev/orch", "6.0"),
                ("remote-session://dev/gate", "7.0"),
            ],
            &HashSet::new(),
            &yggterm_core::row_set_outline::RowArrangement::default(),
        );
        assert_eq!(
            flat,
            vec![
                ("remote-session://dev/orch".to_string(), 1),
                ("remote-session://dev/gate".to_string(), 1),
            ],
            "two books, both top level"
        );
        let nested = live_rows_for_seats(
            &[
                ("remote-session://dev/orch", "6.0"),
                ("remote-session://dev/gate", "6.1"),
            ],
            &HashSet::new(),
            &yggterm_core::row_set_outline::RowArrangement::default(),
        );
        assert_eq!(
            nested,
            vec![
                ("remote-session://dev/orch".to_string(), 1),
                ("remote-session://dev/gate".to_string(), 2),
            ],
            "the same rows, reseated, must nest — a stale cache entry would not"
        );
    }

    #[test]
    fn live_session_drag_drop_reorders_live_group() {
        let path_a = "remote-session://dev/a";
        let path_b = "remote-session://dev/b";
        let path_c = "remote-session://dev/c";
        let mut session_a = test_live_shell_session(path_a);
        session_a.source = SessionSource::LiveSsh;
        session_a.host_label = "dev".to_string();
        let mut session_b = test_live_shell_session(path_b);
        session_b.source = SessionSource::LiveSsh;
        session_b.host_label = "dev".to_string();
        let mut session_c = test_live_shell_session(path_c);
        session_c.source = SessionSource::LiveSsh;
        session_c.host_label = "dev".to_string();
        let live_sessions = vec![session_a.clone(), session_b.clone(), session_c.clone()];
        let mut expanded = HashSet::new();
        expanded.insert("__live_sessions__".to_string());
        let rows = merged_sidebar_rows(&[], &[], &[], &live_sessions, &expanded);
        let target_row = rows
            .iter()
            .find(|row| row.full_path == path_b && row.depth == 1)
            .expect("target live row");
        let target = resolve_drag_drop_target(
            &rows,
            &[path_c.to_string()],
            target_row,
            DragDropPlacement::Before,
        )
        .expect("live session row should accept live-session drop");
        let reordered =
            live_session_reordered_paths_for_drop(&live_sessions, &[path_c.to_string()], &target)
                .expect("live session reorder plan");
        assert_eq!(reordered, vec![path_a, path_c, path_b]);

        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session(path_a));
        shell.server.apply_snapshot(ServerUiSnapshot {
            apps: Vec::new(),
            active_session_path: Some(path_a.to_string()),
            active_session: Some(snapshot_session_view_for_ui(session_a.clone())),
            active_view_mode: WorkspaceViewMode::Terminal,
            remote_machines: Vec::new(),
            ssh_targets: Vec::new(),
            live_sessions: vec![
                snapshot_session_view_for_ui(session_a),
                snapshot_session_view_for_ui(session_b),
                snapshot_session_view_for_ui(session_c),
            ],
        });
        assert!(shell.server.replace_live_session_order(&reordered).changed);
        assert_eq!(
            shell
                .server
                .live_sessions()
                .iter()
                .map(|session| session.session_path.as_str())
                .collect::<Vec<_>>(),
            vec![path_a, path_c, path_b]
        );
    }

    #[test]
    fn live_session_drag_drop_persists_order_to_daemon() {
        let source = SHELL_SOURCE;
        let start = source
            .find("fn queue_drop_current_drag_target")
            .expect("drop handler");
        let end = source[start..]
            .find("fn live_session_reordered_paths_for_drop")
            .map(|offset| start + offset)
            .expect("next reorder helper");
        let handler = &source[start..end];
        assert!(
            handler.contains("shell.server.replace_live_session_order(&reordered_paths)"),
            "drag/drop should optimistically update the visible live-session order"
        );
        assert!(
            handler.contains("reorder_live_sessions_scoped("),
            "drag/drop must also persist the order through the daemon, otherwise GUI restart restores the old order"
        );
        assert!(
            handler.contains("gui_row_order_scope()"),
            "drag/drop reorders must carry this GUI's ledger scope so per-client arrangements survive"
        );
        assert!(
            handler.contains("update.summary()"),
            "the status line must show what actually applied, not a fixed 'reordered' sentence"
        );
        assert!(
            handler.contains("LiveSessionOrderUpdate::from_message("),
            "the daemon's honest answer must be parsed, not shown raw or discarded"
        );
    }

    #[test]
    fn browser_tree_refresh_loop_rearms_remote_machine_refreshes() {
        // Regression lock for the 2026-07-03 "broken truth stage" incident:
        // remote-machine refreshes were only re-armed by initial server sync
        // and by the tail of a completed refresh. One deferred tick (active
        // terminal) killed the chain for the GUI's lifetime, freezing the cwd
        // tree + start page on scan data that was days stale. The periodic
        // browser-tree loop must re-arm the remote truth stage every tick.
        let source = SHELL_SOURCE;
        let start = source
            .find("if !browser_tree_refresh_loop_started.swap(true, Ordering::SeqCst)")
            .expect("browser tree refresh loop");
        let end = source[start..]
            .find("sleep(Duration::from_millis(wait_ms)).await")
            .map(|offset| start + offset)
            .expect("loop sleep");
        let loop_body = &source[start..end];
        assert!(
            loop_body.contains("maybe_spawn_missing_remote_machine_refreshes(state)"),
            "the periodic loop must re-arm remote machine refreshes; without it the refresh chain dies on the first deferred tick"
        );
        assert!(
            loop_body.contains("maybe_spawn_missing_managed_cli_refreshes(state)"),
            "the periodic loop must also re-arm managed CLI refreshes for the same chain-death reason"
        );
    }

