    #[test]
    fn merged_sidebar_rows_project_kept_remote_live_sessions_into_their_own_cwd_folders() {
        let make_live = |session_path: &str, title: &str, cwd: &str| {
            let mut live = test_live_shell_session(session_path);
            live.id = session_path
                .rsplit('/')
                .next()
                .expect("session id")
                .to_string();
            live.title = title.to_string();
            live.kind = SessionKind::Codex;
            live.host_label = "dev".to_string();
            live.source = SessionSource::LiveSsh;
            live.remote_deploy_state = RemoteDeployState::Ready;
            live.ssh_target = Some("dev".to_string());
            live.metadata = vec![
                SessionMetadataEntry {
                    label: "Cwd",
                    value: cwd.to_string(),
                },
                SessionMetadataEntry {
                    label: "Runtime Persistence",
                    value: "keep-alive".to_string(),
                },
            ];
            live
        };
        let samplenotes_path = "remote-session://dev/019d0000-0000-7000-8000-000000000001";
        let samplescripts_path = "remote-session://dev/019d0000-0000-7000-8000-000000000002";
        let rows = merged_sidebar_rows(
            &[],
            &[RemoteMachineSnapshot {
                cli_presence: Vec::new(),
                apps: Vec::new(),
                machine_key: "dev".to_string(),
                label: "dev [ok]".to_string(),
                ssh_target: "dev".to_string(),
                prefix: None,
                remote_binary_expr: None,
                remote_deploy_state: RemoteDeployState::Ready,
                health: RemoteMachineHealth::Healthy,
                sessions: Vec::new(),
            }],
            &[],
            &[
                make_live(samplenotes_path, "samplenotes", "/home/user/git/samplenotes"),
                make_live(samplescripts_path, "erome systemd", "/home/user/git/samplescripts"),
            ],
            &HashSet::from_iter([
                "__live_sessions__".to_string(),
                "__remote_machine__/dev".to_string(),
                "__remote_folder__/dev/home/user/git".to_string(),
                "__remote_folder__/dev/home/user/git/samplenotes".to_string(),
                "__remote_folder__/dev/home/user/git/samplescripts".to_string(),
            ]),
        );

        let descendant_paths = |folder_path: &str| {
            let folder_index = rows
                .iter()
                .position(|row| row.full_path == folder_path)
                .unwrap_or_else(|| panic!("missing folder {folder_path}"));
            let folder_depth = rows[folder_index].depth;
            rows.iter()
                .skip(folder_index + 1)
                .take_while(|row| row.depth > folder_depth)
                .map(|row| row.full_path.as_str())
                .collect::<Vec<_>>()
        };
        let samplenotes_descendants = descendant_paths("__remote_folder__/dev/home/user/git/samplenotes");
        let samplescripts_descendants =
            descendant_paths("__remote_folder__/dev/home/user/git/samplescripts");

        assert!(samplenotes_descendants.contains(&samplenotes_path));
        assert!(!samplenotes_descendants.contains(&samplescripts_path));
        assert!(samplescripts_descendants.contains(&samplescripts_path));
        assert!(!samplescripts_descendants.contains(&samplenotes_path));
        assert_eq!(
            rows.iter().filter(|row| row.full_path == samplenotes_path).count(),
            2
        );
        assert_eq!(
            rows.iter()
                .filter(|row| row.full_path == samplescripts_path)
                .count(),
            2
        );
    }

    #[test]
    fn merged_sidebar_rows_reject_stale_remote_metadata_live_candidates() {
        let remote_sessions = (0..5)
            .map(|ix| RemoteScannedSession {
                kind: None,
                session_path: format!("remote-session://oc/runtime-{ix}"),
                session_id: format!("runtime-{ix}"),
                cwd: "/home/user".to_string(),
                started_at: "2026-05-04T00:00:00Z".to_string(),
                modified_epoch: ix,
                event_count: 1,
                user_message_count: 1,
                assistant_message_count: 0,
                title_hint: format!("Remote candidate {ix}"),
                recent_context: String::new(),
                cached_precis: Some(format!("metadata candidate {ix}")),
                cached_summary: None,
                live_runtime: true,
                title_is_explicit: false,
                storage_path: format!("/home/user/.codex/sessions/runtime-{ix}.jsonl"),
            })
            .collect::<Vec<_>>();
        let remote_machines = vec![RemoteMachineSnapshot {
            cli_presence: Vec::new(),
            apps: Vec::new(),
            machine_key: "oc".to_string(),
            label: "oc [ok]".to_string(),
            ssh_target: "oc".to_string(),
            prefix: None,
            remote_binary_expr: None,
            remote_deploy_state: RemoteDeployState::Ready,
            health: RemoteMachineHealth::Healthy,
            sessions: remote_sessions.clone(),
        }];
        let live_sessions = remote_sessions
            .iter()
            .take(4)
            .map(|scanned| {
                let mut session = test_live_shell_session(&scanned.session_path);
                session.id = scanned.session_id.clone();
                session.title = scanned.title_hint.clone();
                session.kind = SessionKind::Codex;
                session.host_label = "oc".to_string();
                session.source = SessionSource::LiveSsh;
                session.remote_deploy_state = RemoteDeployState::Ready;
                session.ssh_target = Some("oc".to_string());
                session
            })
            .collect::<Vec<_>>();

        let rows = merged_sidebar_rows(
            &[],
            &remote_machines,
            &[],
            &live_sessions,
            &HashSet::from(["__live_sessions__".to_string()]),
        );
        let live_rows = rows
            .iter()
            .skip_while(|row| row.full_path != "__live_sessions__")
            .skip(1)
            .take_while(|row| row.depth > 0)
            .filter(|row| row.kind == BrowserRowKind::Session)
            .collect::<Vec<_>>();

        assert_eq!(live_rows.len(), 4);
        assert!(
            live_rows
                .iter()
                .all(|row| row.full_path != "remote-session://oc/runtime-4"),
            "remote scan metadata must not create an extra Live Sessions row"
        );
    }
