    /// A row whose host is live but whose gate is shut: the exact state the
    /// live trace caught on 2026-08-11, where a click registered an open
    /// attempt, the mount that would have marked it Ready was skipped as
    /// redundant, and the idle agent never emitted the meaningful byte the
    /// fast-ready path waits for.
    fn shell_with_a_live_host_behind_a_shut_gate(session_path: &str) -> ShellState {
        let bootstrap = test_shell_bootstrap_with_active_session(session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server_busy = false;
        shell.window_focused = true;
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        shell.retain_terminal_session_path(session_path);
        shell.bump_terminal_mount_epoch_for_session(session_path);
        // Ready once in this host's life, then superseded by a fresh attempt
        // that will never observe anything.
        shell.terminal_sessions_reached_ready
            .insert(session_path.to_string());
        shell.begin_terminal_open_attempt(session_path, "req-open", 1, "hot_open_row");
        shell.terminal_resume_ready_paths.remove(session_path);
        assert!(
            shell.remote_resume_input_gate_is_shut(session_path),
            "scaffold must reproduce the shut gate"
        );
        shell
    }

    /// The gate that keeps the once-a-second deadline tick from re-rendering
    /// the whole app root while it has nothing to do. It is only safe if
    /// "inert" really does imply "writes nothing", and if it never answers
    /// inert while the escape hatch still has a clock running — a gate that got
    /// the second half wrong would strand exactly the sessions the deadline
    /// exists to rescue.
    #[test]
    fn an_inert_input_gate_tick_really_writes_nothing() {
        let session_path = "remote-cc://dev/gate-test-inert-tick-writes-nothing";
        let mut shell = shell_with_a_live_host_behind_a_shut_gate(session_path);
        let now = 900_000_u64;

        // At rest with the window unfocused: no candidate, and no clock left
        // over from an earlier refusal.
        shell.input_gate_denied_since_ms.clear();
        shell.input_gate_stuck_reported.clear();
        shell.window_focused = false;
        assert!(
            shell.input_gate_deadline_tick_is_inert(),
            "no candidate and no armed clock is the at-rest case the gate is for"
        );

        // Running the real tick anyway must change nothing observable — that is
        // what earns the right to skip it.
        let ready_before = shell.terminal_resume_ready_paths.clone();
        assert_eq!(shell.tick_input_gate_deadline_for_candidate(None, now), None);
        assert!(shell.input_gate_denied_since_ms.is_empty());
        assert!(shell.input_gate_stuck_reported.is_empty());
        assert_eq!(
            shell.terminal_resume_ready_paths, ready_before,
            "an inert tick must not touch the readiness set"
        );

        // And the converse, which is the half that could strand a session: a
        // candidate behind a SHUT gate must never read as inert, or the loop
        // stops taking the write and the escape hatch never fires.
        shell.window_focused = true;
        assert!(
            !shell.input_gate_deadline_tick_is_inert(),
            "a focused row behind a shut gate is the deadline's whole job — \
             skipping it would strand the surface the hatch exists to restore"
        );
        assert_eq!(
            shell.tick_input_gate_deadline_for_candidate(Some(session_path.to_string()), now),
            None,
            "first look only arms the clock"
        );
        assert!(
            !shell.input_gate_denied_since_ms.is_empty(),
            "scaffold must leave a running clock for the next assertion to mean anything"
        );
        assert!(
            !shell.input_gate_deadline_tick_is_inert(),
            "a session already being refused must keep ticking — skipping it here \
             would strand the surface the escape hatch exists to restore"
        );
    }

    // ⛔ The tick only ever acts on the CANDIDATE, so "is any clock running
    // anywhere" was the wrong question and it was asked once a second forever.
    // A row the owner has switched away from leaves its entry behind — nothing
    // removes it while a candidate exists — and that one leftover pinned a full
    // app-root re-render at 1 Hz for the rest of the process.
    #[test]
    fn a_stale_gate_clock_from_another_row_no_longer_pins_a_render_per_second() {
        let focused = "remote-cc://example-host/gate-focused-open";
        let mut shell = shell_with_a_live_host_behind_a_shut_gate(focused);
        // Open the focused row's gate: the tick's only job for it is to remove
        // its own entries, and it has none.
        shell.terminal_resume_ready_paths.insert(focused.to_string());
        assert!(!shell.remote_resume_input_gate_is_shut(focused));
        shell.input_gate_denied_since_ms.clear();
        shell.input_gate_stuck_reported.clear();
        assert!(shell.input_gate_deadline_tick_is_inert());

        let other = "remote-cc://example-host/gate-row-since-left".to_string();
        shell.input_gate_denied_since_ms.insert(other.clone(), 1);
        shell.input_gate_stuck_reported.insert(other.clone());
        assert!(
            shell.input_gate_deadline_tick_is_inert(),
            "another row's leftovers are not work for a tick that can only touch the candidate"
        );

        // The proof that skipping is safe: running the real tick anyway leaves
        // those leftovers exactly where they were.
        let denied_before = shell.input_gate_denied_since_ms.clone();
        let reported_before = shell.input_gate_stuck_reported.clone();
        assert_eq!(
            shell.tick_input_gate_deadline_for_candidate(Some(focused.to_string()), 900_000),
            None
        );
        assert_eq!(shell.input_gate_denied_since_ms, denied_before);
        assert_eq!(shell.input_gate_stuck_reported, reported_before);

        // The candidate's OWN clock is still work, and so is the clear-all arm.
        shell.input_gate_denied_since_ms.insert(focused.to_string(), 1);
        assert!(
            !shell.input_gate_deadline_tick_is_inert(),
            "the focused row's own clock must still be removed"
        );
        shell.window_focused = false;
        assert!(
            !shell.input_gate_deadline_tick_is_inert(),
            "no candidate with leftovers still owes a clear-all"
        );
    }

    // ⛔ "A card is up" is a different question from "the card would change",
    // and answering the first spent a render per second for the card's whole
    // life — including on a row whose surface is already broken, which is the
    // worst moment to be spending them.
    #[test]
    fn a_card_that_would_not_change_no_longer_costs_a_render_per_second() {
        let session_path = "remote-cc://example-host/card-inert";
        let mut shell = shell_with_a_live_host_behind_a_shut_gate(session_path);
        shell.settings.in_app_notifications = true;
        let job_key = terminal_resume_notification_job_key(session_path);
        // A card that words its own situation — the shape every site except the
        // stage-driven one raises, including the seed's refusal.
        shell.upsert_job_notification(
            job_key.clone(),
            NotificationTone::Warning,
            "Terminal Screen Unavailable",
            "the daemon answered an empty screen",
            None,
            false,
            Some(session_path.to_string()),
        );
        // One refresh writes exactly what the update says; the predicate must
        // then agree, because both read the same computation.
        assert!(shell.refresh_terminal_restore_card());
        assert!(
            shell.restore_card_refresh_is_inert(),
            "writer and predicate must agree by construction, or the card either \
             freezes or never stops re-rendering"
        );

        // A stage that actually advances is work again.
        let attempt_id = shell
            .terminal_open_attempt_by_session
            .get(session_path)
            .cloned()
            .expect("the scaffold opened an attempt");
        shell
            .terminal_open_attempts
            .get_mut(&attempt_id)
            .expect("attempt")
            .first_output_at_ms = Some(1);
        assert!(
            !shell.restore_card_refresh_is_inert(),
            "a stage advance moves the bar and must take the write"
        );
        assert!(shell.refresh_terminal_restore_card());
        assert!(shell.restore_card_refresh_is_inert());

        // And with no card at all there is nothing to refresh.
        shell.clear_job_notification(&job_key);
        assert!(shell.restore_card_refresh_is_inert());
        assert!(!shell.refresh_terminal_restore_card());
    }

    /// The owner's "once in a while a session stops responding to inputs".
    /// 2026-08-16 ALL-sessions fix: deadlines are 0 — immediate restore.
    #[test]
    fn a_row_that_never_proved_ready_still_gets_its_keyboard_back() {
        let session_path = "remote-cc://dev/gate-test-unproven-but-live";
        let mut shell = shell_with_a_live_host_behind_a_shut_gate(session_path);
        // The client's memory of `ready` is what is missing — not the PTY.
        shell.terminal_sessions_reached_ready.remove(session_path);
        shell.terminal_attach_in_flight.insert(session_path.to_string());
        let now = 900_000_u64;

        assert!(
            !shell.terminal_session_host_reusable_for_reveal(session_path),
            "scaffold must reproduce the unprovable row the old branch gave up on"
        );
        assert!(
            shell.daemon_owns_session_runtime(session_path),
            "the PTY must still be live — that is what makes restoring safe"
        );

        // With 0 deadline, first tick arms, second tick restores immediately.
        assert_eq!(
            shell.tick_input_gate_deadline_for_candidate(Some(session_path.to_string()), now),
            None,
            "first tick arms the clock"
        );
        assert_eq!(
            shell.tick_input_gate_deadline_for_candidate(
                Some(session_path.to_string()),
                now + 1
            ),
            Some(session_path.to_string()),
            "2026-08-16: immediate restore — PTY live, no 60s wait"
        );
        assert!(shell.terminal_resume_ready_paths.contains(session_path));
        assert!(!shell.terminal_attach_in_flight.contains(session_path));
    }

    /// ⛔ The half that must NOT become permissive. With no PTY behind it the
