    #[test]
    fn js_debug_trace_write_decision_throttles_floods_but_keeps_rare_events() {
        // Regression for the UI freeze ([[finding-ui-freeze-js-debug-trace-flood]]):
        // a reveal/replay onData burst-storm floods js_debug -> synchronous disk
        // writes on the UI thread. The write must be rate-limited per window,
        // dropping only the flood and reporting the dropped count once.
        // This is the sole user of these module statics, so it is deterministic
        // despite the statics persisting across tests.
        let base = 5_000_000u64;
        // First event opens a fresh window: writes, nothing dropped yet.
        assert_eq!(js_debug_trace_write_decision(base), (true, 0));
        // Remaining events up to the cap (same window) all write.
        for i in 1..JS_DEBUG_TRACE_WINDOW_MAX {
            assert_eq!(
                js_debug_trace_write_decision(base + i),
                (true, 0),
                "event {i} under the cap must write"
            );
        }
        // Over the cap within the window: dropped (no write).
        let mut dropped = 0u64;
        for i in 0..50 {
            let (write, _) = js_debug_trace_write_decision(base + 100 + i);
            if !write {
                dropped += 1;
            }
        }
        assert_eq!(dropped, 50, "every over-cap event in the window is shed");
        // The first write of the NEXT window flushes the dropped count once.
        assert_eq!(
            js_debug_trace_write_decision(base + JS_DEBUG_TRACE_WINDOW_MS),
            (true, 50)
        );
        // ...and the dropped counter is cleared for the following window.
        assert_eq!(
            js_debug_trace_write_decision(base + 2 * JS_DEBUG_TRACE_WINDOW_MS),
            (true, 0)
        );
    }
    #[test]
    fn open_reassert_reuses_the_host_while_its_first_attach_is_settling() {
        // Regression for the "each reveal constructs twice" blink: the
        // re-assert that lands right after an open request completes (the
        // latest_open_request_id bump re-runs the mount-key effect) must
        // REVEAL the just-mounted host, not cold-remount it — the reveal
        // path requires was_ever_ready, which a session being born cannot
        // satisfy, so this used to bump epoch N to N+1 ~0.6s after every
        // first mount and tear down the in-flight attach.
        let active_session_path = "remote-cc://dev/settling-birth";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server_busy = false;
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        let (first_epoch, reused_first, _) =
            shell.resolve_active_open_mount_epoch(active_session_path, 1_000);
        assert!(!reused_first, "a genuine first mount must cold-mount");
        shell
            .terminal_attach_in_flight
            .insert(active_session_path.to_string());
        let attempt_id =
            shell.begin_terminal_open_attempt(active_session_path, "req-birth", 1, "open_path");
        if let Some(attempt) = shell.terminal_open_attempts.get_mut(&attempt_id) {
            attempt.started_at_ms = 1_000;
        }
        // The re-assert 600ms later, attach still in flight: reuse, no bump.
        let (epoch, reused, settled) =
            shell.resolve_active_open_mount_epoch(active_session_path, 1_600);
        assert!(reused, "a settling first attach must be revealed, not remounted");
        assert!(!settled);
        assert_eq!(epoch, first_epoch, "no epoch bump while the attach settles");
        // Once the attempt ages past its recovery budget without ready, a
        // re-assert may cold-remount again (the hung-attach escape hatch).
        let stale_now = 1_000 + STARTUP_TERMINAL_RESTORE_RECOVERY_MS + 1_000;
        let (stale_epoch, stale_reused, _) =
            shell.resolve_active_open_mount_epoch(active_session_path, stale_now);
        assert!(!stale_reused, "a hung attach must not pin the host forever");
        assert!(stale_epoch > first_epoch);
    }
    #[test]
    fn futile_cold_remounts_settle_instead_of_looping_forever() {
        // Regression for the idle "blink" loop
        // ([[finding-cc-blink-dead-session-remount-loop]]): a live session whose
        // open-attempt never latches Ready never satisfies
        // terminal_session_is_retained_live, so each periodic open re-assert would
        // cold-remount it forever (epoch bump -> bootstrap_reset -> viewport
        // re-seed). After a futile streak the existing host must be REUSED with no
        // epoch bump so the session can settle, and the loop must stay broken.
        let active_session_path = "remote-session://dev/never-ready";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server_busy = false;
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        // A mounted host that is NOT retained-live (active remote + bootstrap lease,
        // no ready signal == is_retained_live false), like a never-Ready attempt.
        shell.retain_terminal_session_path(active_session_path);
        shell.bump_terminal_mount_epoch_for_session(active_session_path);
        shell
            .terminal_bootstrap_owner_by_session
            .insert(active_session_path.to_string(), "owner:test".to_string());
        shell
            .terminal_bootstrap_lease_by_session
            .insert(active_session_path.to_string(), "lease:test".to_string());
        assert!(!shell.terminal_session_is_retained_live(active_session_path));

        // First cold remount bumps the epoch (a genuine first reveal always mounts).
        let (_, reused_first, settled_first) =
            shell.resolve_active_open_mount_epoch(active_session_path, 1_000);
        assert!(!reused_first && !settled_first, "first cold remount must bump");
        let epoch_after_first = *shell
            .terminal_mount_epochs
            .get(active_session_path)
            .expect("epoch present after first cold remount");

        // Re-asserts within the time window keep cold-remounting (epoch climbs).
        let mut now = 1_000u64;
        for _ in 0..5 {
            now += 1_000;
            shell.resolve_active_open_mount_epoch(active_session_path, now);
        }
        let epoch_before_settle = *shell
            .terminal_mount_epochs
            .get(active_session_path)
            .expect("epoch present while churning");
        assert!(
            epoch_before_settle > epoch_after_first,
            "epoch keeps climbing while the futile streak is within budget"
        );

        // Past BOTH the count and time thresholds: settle (reuse, no epoch bump).
        now += TERMINAL_FUTILE_COLD_REMOUNT_MS;
        let (settled_epoch, reused, settled) =
            shell.resolve_active_open_mount_epoch(active_session_path, now);
        assert!(settled, "a futile streak must settle instead of remounting");
        assert!(!reused, "settling reuses the host but is not a genuine live reveal");
        assert_eq!(
            settled_epoch, epoch_before_settle,
            "settling reuses the existing epoch — no remount, no re-seed"
        );

        // Subsequent re-asserts keep the SAME epoch: the blink loop is broken.
        now += 60_000;
        let (epoch_again, _, settled_again) =
            shell.resolve_active_open_mount_epoch(active_session_path, now);
        assert!(settled_again);
        assert_eq!(
            epoch_again, epoch_before_settle,
            "no further remounts once settled"
        );

        // Once the session genuinely becomes retained-live, the streak clears and
        // the live host is reused with no churn (and a later death re-arms the cap).
        shell
            .terminal_bootstrap_owner_by_session
            .remove(active_session_path);
        shell
            .terminal_bootstrap_lease_by_session
            .remove(active_session_path);
        shell
            .terminal_resume_ready_paths
            .insert(active_session_path.to_string());
        assert!(shell.terminal_session_is_retained_live(active_session_path));
        now += 1_000;
        let (_, reused_live, settled_live) =
            shell.resolve_active_open_mount_epoch(active_session_path, now);
        assert!(reused_live && !settled_live, "live host reused, streak cleared");
        assert!(
            !shell
                .terminal_cold_remount_count
                .contains_key(active_session_path),
            "streak count cleared when the session becomes retained-live"
        );
        assert!(!shell
            .terminal_cold_remount_since_ms
            .contains_key(active_session_path));
    }
    #[test]
    fn retained_host_with_ready_history_is_hot_reusable_on_switch_back() {
        // Regression for the "every session switch feels cold" bug
        // ([[followups-switch-hotness-update-friction]]): a retained host that
        // previously reached ready must stay HOT-reusable on switch-back even
        // after its transient ready flags clear and the open attempt picks up a
        // spurious "xterm surface is empty" problem while it was hidden — as
        // long as the daemon still owns the PTY.
        let active_session_path = "remote-session://dev/hot-switch";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server_busy = false;
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        shell.retain_terminal_session_path(active_session_path);
        shell.bump_terminal_mount_epoch_for_session(active_session_path);
        let attempt_id =
            shell.begin_terminal_open_attempt(active_session_path, "request:hot", 1, "test");
        shell.mark_terminal_open_attempt_ready_for_session(active_session_path, "test_ready");
        // Simulate the hidden-host state: not in resume-ready set, and the
        // attempt now carries an empty-surface problem so has_ready_attempt is
        // false. ready_history (ready_at_ms) is sticky and remains.
        shell.terminal_resume_ready_paths.remove(active_session_path);
        if let Some(attempt) = shell.terminal_open_attempts.get_mut(&attempt_id) {
            attempt.observations = 1;
            attempt.last_observed_ready = false;
            attempt.last_surface_problem =
                Some("active terminal host exists but xterm surface is empty".to_string());
        }
        assert!(
            !shell.terminal_session_has_ready_attempt(active_session_path),
            "precondition: the transient ready-attempt signal is cleared while hidden"
        );
        // latest_runtime_status is None here -> daemon_owns_session_runtime
        // falls back to true, so the host is reusable (HOT reveal, no remount).
        assert!(
            shell.terminal_session_is_retained_live(active_session_path),
            "a retained host that reached ready must be reused on switch-back, not cold-remounted"
        );
        // Safety: if the daemon no longer owns the PTY, fall through to recovery.
        shell.latest_runtime_status = Some(runtime_status_for_test("2.8.1", 0, 12345));
        assert!(
            !shell.terminal_session_is_retained_live(active_session_path),
            "a retained host whose daemon PTY is gone must NOT be reused; it must recover"
        );
    }
    #[test]
    fn reveal_grace_lets_switch_back_reuse_host_despite_stale_recovering_attempt() {
        // The watchdog race left a stale `Recovering` attempt with an
        // invalidating reason. Without a reveal grace that forces a cold
        // remount; with one (opened on switch activation) the host is reused.
        let active_session_path = "remote-session://dev/reveal-grace";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server_busy = false;
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        shell.retain_terminal_session_path(active_session_path);
        shell.bump_terminal_mount_epoch_for_session(active_session_path);
        let attempt_id =
            shell.begin_terminal_open_attempt(active_session_path, "request:rg", 1, "test");
        shell.mark_terminal_open_attempt_ready_for_session(active_session_path, "test_ready");
        shell.terminal_resume_ready_paths.remove(active_session_path);
        // Stale spurious recovering attempt from a prior switch's watchdog race.
        if let Some(attempt) = shell.terminal_open_attempts.get_mut(&attempt_id) {
            attempt.state = TerminalOpenAttemptState::Recovering;
            attempt.last_observed_reason =
                Some("active terminal host exists but xterm surface is empty".to_string());
        }
        // No grace yet -> the stale recovering attempt forces a cold remount.
        assert!(
            !shell.terminal_session_is_retained_live(active_session_path),
            "without a reveal grace a stale recovering attempt must block reuse"
        );
        // Opening the reveal grace (as the activation effect does on switch)
        // lets the host be reused, and the watchdog defers the benign fault.
        shell.terminal_reveal_grace_until_ms.insert(
            active_session_path.to_string(),
            current_millis().saturating_add(RETAINED_REVEAL_EMPTY_GRACE_MS),
        );
        assert!(
            shell.terminal_session_is_retained_live(active_session_path),
            "within the reveal grace the host must be reused (HOT switch-back)"
        );
        assert!(
            !shell.invalidate_retained_remote_non_prompt_surface(
                active_session_path,
                Some("active terminal host exists but xterm surface is empty"),
            ),
            "the watchdog must defer the benign empty-surface fault during the reveal grace"
        );
    }
