    #[test]
    fn reveal_log_records_a_failed_reveal() {
        let active_session_path = "remote-session://oc/reveal-fail";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        let _attempt_id =
            shell.begin_terminal_open_attempt(active_session_path, "req-fail", 2, "open_row");

        shell.fail_terminal_open_attempt_for_session(active_session_path, "boom".to_string());
        assert_eq!(shell.reveal_log.len(), 1);
        let entry = shell.reveal_log.back().expect("reveal entry");
        assert_eq!(entry.outcome, "failed");
        assert_eq!(entry.failure_reason.as_deref(), Some("boom"));

        // The latch is one-shot, so a second failure does not duplicate.
        shell.fail_terminal_open_attempt_for_session(active_session_path, "again".to_string());
        assert_eq!(shell.reveal_log.len(), 1);
    }

    /// ⛔ SHAPE B (2026-08-10): the user clicks a row, switches away before it
    /// mounts, and 60 s later gets a red "did not become interactive in time"
    /// toast about the session they left — plus a `reveal_failed` row blaming
    /// the remote host for a mount WE decided not to make.
    ///
    /// Feed the fix the thing it must catch: an attempt in flight for a session
    /// that is not the active terminal.
    #[test]
    fn a_reveal_cancelled_by_switching_away_is_resolved_and_never_counted_as_a_failure() {
        let active_session_path = "remote-session://oc/reveal-cancel-active";
        let left_behind_path = "remote-session://oc/reveal-cancel-left";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.settings.in_app_notifications = true;
        shell.settings.system_notifications = false;
        shell.settings.notification_sound = false;
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        let attempt_id =
            shell.begin_terminal_open_attempt(left_behind_path, "req-left", 7, "open_row");
        // Long enough that a `ready` outcome would nag about a slow reveal. A
        // cancel must not borrow that voice either — nothing was slow, the user
        // simply left.
        if let Some(attempt) = shell.terminal_open_attempts.get_mut(&attempt_id) {
            attempt.started_at_ms = attempt.started_at_ms.saturating_sub(20_000);
        }

        assert!(
            shell.cancel_terminal_open_attempt_for_inactive_session(
                left_behind_path,
                "switched away before the host could mount",
            ),
            "an attempt still waiting on a skipped bootstrap must be cancelled"
        );

        let attempt = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt survives its cancellation");
        assert_eq!(
            attempt.state,
            TerminalOpenAttemptState::Cancelled,
            "the attempt must be RESOLVED, not left waiting for the 60 s ceiling"
        );
        assert_eq!(shell.reveal_log.len(), 1);
        let entry = shell.reveal_log.back().expect("reveal entry");
        assert_eq!(
            entry.outcome, "cancelled",
            "a switch-away is its own outcome; counting it as `failed` is what made \
             4 of 11 never-ready reveals unfixable by construction"
        );
        assert!(
            shell.notifications.is_empty(),
            "a cancelled reveal must raise NO toast at all: {:?}",
            shell
                .notifications
                .iter()
                .map(|notification| notification.title.clone())
                .collect::<Vec<_>>()
        );
        assert!(
            shell.terminal_session_reveal_attempt_was_cancelled(left_behind_path),
            "the resume-timeout timer stands down on exactly this signal"
        );

        // One-shot, like the failure latch: a second skip tick cannot re-record.
        assert!(
            !shell.cancel_terminal_open_attempt_for_inactive_session(left_behind_path, "again"),
            "an attempt that already has an outcome may not be given a second one"
        );
        assert_eq!(shell.reveal_log.len(), 1);
    }

    /// The other half of the falsifier: feed the guard the case it must NOT
    /// catch. The bootstrap skip also fires transiently for the session the user
    /// just clicked, because the server-side active path lags the click by one
    /// round-trip — cancelling that one is the "session did not mount" bug this
    /// guard is scoped to avoid.
    #[test]
    fn the_active_terminal_session_is_never_cancelled_by_the_bootstrap_skip() {
        let active_session_path = "remote-session://oc/reveal-cancel-guard";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        let attempt_id =
            shell.begin_terminal_open_attempt(active_session_path, "req-active", 8, "open_row");

        assert!(
            !shell
                .cancel_terminal_open_attempt_for_inactive_session(active_session_path, "too eager"),
            "the session being revealed right now is not an abandoned one"
        );
        let attempt = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt");
        assert!(
            matches!(attempt.state, TerminalOpenAttemptState::Pending),
            "the active session's reveal must keep waiting, and keep its ceiling"
        );
        assert!(shell.reveal_log.is_empty());
        assert!(!shell.terminal_session_reveal_attempt_was_cancelled(active_session_path));
    }

    /// A cancelled attempt stands the resume-timeout timer down, so it must not
    /// outlive the reveal it belonged to: the next reveal begins a fresh attempt
    /// and gets its own failure ceiling back.
    #[test]
    fn a_fresh_reveal_after_a_cancel_is_not_stood_down_by_the_old_attempt() {
        let active_session_path = "remote-session://oc/reveal-cancel-rearm-active";
        let session_path = "remote-session://oc/reveal-cancel-rearm";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        shell.begin_terminal_open_attempt(session_path, "req-first", 9, "open_row");
        assert!(
            shell.cancel_terminal_open_attempt_for_inactive_session(session_path, "switched away")
        );
        assert!(shell.terminal_session_reveal_attempt_was_cancelled(session_path));

        // The user comes back to the row.
        shell.begin_terminal_open_attempt(session_path, "req-second", 10, "open_row");
        assert!(
            !shell.terminal_session_reveal_attempt_was_cancelled(session_path),
            "a fresh attempt must clear the stand-down, or this reveal would have \
             no failure ceiling at all"
        );

        // And a genuine failure on the fresh attempt is still recorded as one.
        shell.fail_terminal_open_attempt_for_session(session_path, "boom".to_string());
        let entry = shell.reveal_log.back().expect("reveal entry");
        assert_eq!(entry.outcome, "failed");
    }

    /// The measured 2026-08-29 GUI-host UI-block storm (`11.31`): a mount that had
    /// succeeded and was streaming daemon-forwarded meaningful output had its
    /// open attempt cancelled by the inactive-skip 16 s later ("stopped being
    /// the active terminal before its host could mount" — FALSE: the host HAD
    /// mounted). Cancelling destroyed the ready proof — `was_ever_ready` false
    /// forever, retained-live clause C dead — so every switch-back to the
    /// session cold-remounted (bootstrap_reset + full xterm rebuild + backlog
    /// replay, ~200-400 ms of UI stall per click) until the UI blocked in
    /// ~2 s gaps. A live host must latch ready, not be discarded as unmounted.
    #[test]
    fn cancelling_an_inactive_attempt_with_a_live_host_latches_ready_not_cancelled() {
        let other_active_path = "local://reveal-cancel-live-host-active";
        let session_path = "local://reveal-cancel-live-host";
        let bootstrap = test_shell_bootstrap_with_active_session(other_active_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        // The host record exists: the mount epoch was assigned (the mount_open
        // had succeeded by the time the cancel fired in the measured trace).
        shell.bump_terminal_mount_epoch_for_session(session_path);
        let attempt_id =
            shell.begin_terminal_open_attempt(session_path, "req-live-host", 4, "startup_restore");
        // Real session content arrived through the daemon's forward, but the
        // strict fast-ready refuses on the absent runtime-status manifest —
        // reproducing the exact measured Pending-with-live-output window.
        shell.mark_terminal_open_attempt_first_meaningful_output_for_session(
            session_path,
            "daemon_output",
            false,
            false,
        );
        let attempt = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt");
        assert!(
            attempt.ready_at_ms.is_none()
                && attempt.first_meaningful_output_at_ms.is_some()
                && matches!(attempt.state, TerminalOpenAttemptState::Pending),
            "scaffold must reproduce the measured pending-with-live-output state"
        );

        // The inactive-skip cancel fires while another session is active.
        let cancelled = shell
            .cancel_terminal_open_attempt_for_inactive_session(
                session_path,
                "the reveal was cancelled: this session stopped being the active terminal",
            );
        assert!(
            !cancelled,
            "a live host must not be discarded as 'stopped before its host could mount'"
        );
        let attempt = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt");
        assert!(
            attempt.ready_at_ms.is_some()
                && matches!(attempt.state, TerminalOpenAttemptState::Ready),
            "the attempt must latch ready — the reveal it waited for already happened"
        );
        assert!(
            shell.terminal_session_was_ever_ready(session_path),
            "the sticky ready proof must survive for the next switch-back"
        );

        // The user clicks back: the open path retains the session (the MRU was
        // fed by the post-activation retains), and retained-live clause C —
        // the hot reveal — must now recognize the host as revealable, so the
        // switch takes the same-epoch reveal instead of a cold remount.
        shell.note_terminal_activation_mru(session_path);
        shell.retain_terminal_session_path(session_path);
        assert!(
            shell.terminal_session_is_retained_live(session_path),
            "clause C must see host + was_ever_ready + daemon ownership: no remount"
        );
    }

    /// The measured 2026-08-29 pump (`11.32` family, watchdog seam): a mount
    /// that had succeeded — `mount_open` success, `attach_ready`, daemon
    /// forward streaming meaningful output — sat Pending because fast-ready is
    /// structurally ineligible for remote-session rows (the local runtime
    /// manifest never lists their runtime keys and the content is not
    /// prompt-like). The retained-fault-recovery watchdog read that Pending as
    /// a fault and remounted the HEALTHY host twice per burst
    /// (`MAX_REARMS=2`), bursts repeating every cooldown — each remount a full
    /// bootstrap_reset + xterm rebuild + `clear_to_empty` + rehydrate, the
    /// felt per-switch lag. A live streaming host must latch ready and
    /// consume no remount budget.
    #[test]
    fn the_fault_watchdog_latches_ready_instead_of_remounting_a_live_host() {
        let session_path = "remote-session://dev/watchdog-live-host";
        let bootstrap = test_shell_bootstrap_with_active_session(session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        shell.retain_terminal_session_path(session_path);
        shell.bump_terminal_mount_epoch_for_session(session_path);
        shell.terminal_attach_in_flight.insert(session_path.to_string());
        let attempt_id =
            shell.begin_terminal_open_attempt(session_path, "req-watchdog", 7, "retained_fault_recovery");
        // The mount succeeded and the daemon forward streamed meaningful
        // output; fast-ready stays ineligible (no runtime manifest, not
        // prompt-like) — reproducing the measured Pending-with-live-output
        // state the watchdog then misread as a fault.
        shell.mark_terminal_open_attempt_first_meaningful_output_for_session(
            session_path,
            "daemon_output",
            false,
            false,
        );
        // Age the attempt past its rearm threshold.
        let started = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt")
            .started_at_ms;
        shell
            .terminal_open_attempts
            .get_mut(&attempt_id)
            .expect("attempt")
            .started_at_ms = started.saturating_sub(3_600_000);
        let now = started + 3_600_000;

        let rearm = shell.rearm_stale_retained_fault_recovery(session_path, now);
        assert!(
            !rearm,
            "a live streaming host must not be remounted by the watchdog"
        );
        let attempt = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt");
        assert!(
            attempt.ready_at_ms.is_some()
                && matches!(attempt.state, TerminalOpenAttemptState::Ready),
            "the watchdog must latch ready for a host that already streamed output"
        );
        assert_eq!(
            attempt.rearm_count, 0,
            "a healthy host consumes no remount budget"
        );
        assert!(
            shell.terminal_session_was_ever_ready(session_path),
            "the sticky ready proof must survive for the next switch-back"
        );
    }

    /// The negative arm: without live output the watchdog is still the
    /// machinery that rescues a genuinely stuck reveal — the remount budget
    /// must be consumed exactly as before.
    #[test]
    fn the_fault_watchdog_still_remounts_an_attempt_with_no_live_output() {
        let session_path = "remote-session://dev/watchdog-stuck";
        let bootstrap = test_shell_bootstrap_with_active_session(session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        shell.retain_terminal_session_path(session_path);
        shell.bump_terminal_mount_epoch_for_session(session_path);
        shell.terminal_attach_in_flight.insert(session_path.to_string());
        let attempt_id =
            shell.begin_terminal_open_attempt(session_path, "req-stuck", 8, "retained_fault_recovery");
        let started = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt")
            .started_at_ms;
        shell
            .terminal_open_attempts
            .get_mut(&attempt_id)
            .expect("attempt")
            .started_at_ms = started.saturating_sub(3_600_000);

        let rearm = shell.rearm_stale_retained_fault_recovery(
            session_path,
            started + 3_600_000,
        );
        assert!(
            rearm,
            "a stuck attempt with no output still needs the watchdog remount"
        );
        let attempt = shell
            .terminal_open_attempts
            .get(&attempt_id)
            .expect("attempt");
        assert_eq!(
            attempt.rearm_count, 1,
            "the remount budget is consumed by genuinely stuck attempts"
        );
    }

    /// The 60 s timer raises its toast ITSELF and only then latches the failure,
    /// so resolving the attempt is not enough — the timer has to be told. Both
    /// arms of the stand-down, and both of its refusals.
    #[test]
    fn the_resume_timeout_stands_down_only_when_nobody_is_waiting() {
        let active_session_path = "remote-session://oc/stand-down-active";
        let cancelled_path = "remote-session://oc/stand-down-cancelled";
        let no_attempt_path = "remote-session://oc/stand-down-no-attempt";
        let waiting_path = "remote-session://oc/stand-down-waiting";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);

        // Arm 1: the reveal was cancelled when its bootstrap was skipped.
        shell.begin_terminal_open_attempt(cancelled_path, "req-c", 1, "open_row");
        assert!(shell.cancel_terminal_open_attempt_for_inactive_session(cancelled_path, "left"));
        assert_eq!(
            shell.terminal_resume_timeout_should_stand_down(cancelled_path),
            Some("reveal_cancelled")
        );

        // Arm 2: nothing ever began an attempt for this session, and the user is
        // not looking at it. Measured live 2026-08-10 — the ceiling fired at
        // exactly 60 s with no `reveal_failed` beside it, because there was
        // nothing to fail. The toast fired anyway.
        assert_eq!(
            shell.terminal_resume_timeout_should_stand_down(no_attempt_path),
            Some("no_open_attempt_on_an_inactive_session")
        );

        // Refusal 1: the session the user is actually looking at must still be
        // told when its terminal never came up — even with no attempt recorded.
        assert_eq!(
            shell.terminal_resume_timeout_should_stand_down(active_session_path),
            None,
            "a user staring at a dead terminal must still be told"
        );

        // Refusal 2: an inactive session whose reveal is genuinely still in
        // flight keeps its ceiling. Nothing decided against this mount.
        shell.begin_terminal_open_attempt(waiting_path, "req-w", 2, "open_row");
        assert_eq!(
            shell.terminal_resume_timeout_should_stand_down(waiting_path),
            None,
            "a live attempt is a reveal somebody may still be waiting on"
        );
    }

    /// Trading a false failure for a stuck lease would not be a fix. The
    /// stand-down must do every scrap of cleanup the 60 s failure used to do.
    #[test]
    fn standing_down_releases_everything_the_failure_path_released() {
        let active_session_path = "remote-session://oc/stand-down-cleanup-active";
        let session_path = "remote-session://oc/stand-down-cleanup";
        let bootstrap = test_shell_bootstrap_with_active_session(active_session_path);
        let mut shell = ShellState::new(bootstrap);
        shell.server.set_view_mode(WorkspaceViewMode::Terminal);
        shell
            .terminal_attach_in_flight
            .insert(session_path.to_string());
        shell
            .terminal_resume_ready_paths
            .insert(session_path.to_string());
        shell
            .terminal_bootstrap_lease_by_session
            .insert(session_path.to_string(), "lease-1".to_string());

        shell.stand_down_remote_terminal_resume_timeout(session_path, "lease-1");

        assert!(!shell.terminal_attach_in_flight.contains(session_path));
        assert!(!shell.terminal_resume_ready_paths.contains(session_path));
        assert!(
            !shell
                .terminal_bootstrap_lease_by_session
                .contains_key(session_path),
            "the bootstrap lease must be released, or the next reveal of this row \
             is skipped for an owner that no longer exists"
        );
    }

    #[test]
