    #[test]
    fn background_copy_job_retry_ready_skips_passive_failures() {
        let now = 500;
        let retry_key = background_copy_retry_key("summary", "remote-session://dev/test");
        let mut retry_after = HashMap::new();
        let mut passive_failures = HashSet::new();

        assert!(background_copy_job_retry_ready(
            &retry_after,
            &passive_failures,
            "summary",
            "remote-session://dev/test",
            now,
        ));

        retry_after.insert(retry_key.clone(), now + 1_000);
        assert!(!background_copy_job_retry_ready(
            &retry_after,
            &passive_failures,
            "summary",
            "remote-session://dev/test",
            now,
        ));

        retry_after.insert(retry_key.clone(), now);
        passive_failures.insert(retry_key);
        assert!(!background_copy_job_retry_ready(
            &retry_after,
            &passive_failures,
            "summary",
            "remote-session://dev/test",
            now,
        ));
    }
    // Regression guard for the title-regen loop (2026-06-14): a SUCCESSFUL passive title
    // generation must impose a cooldown that outlasts a scan cycle, so a generated title
    // clobbered back to a fallback isn't re-generated every cycle (~12 LLM calls/hr/session).
    #[test]
    fn title_success_cooldown_outlasts_a_scan_cycle() {
        let now = 1_000_000u64;
        let key = background_copy_retry_key("title", "remote-session://dev/test");
        let mut retry_after = HashMap::new();
        let passive_failures = HashSet::new();
        // A success sets now + BACKGROUND_COPY_SUCCESS_COOLDOWN_MS (not a clear).
        retry_after.insert(key, now + BACKGROUND_COPY_SUCCESS_COOLDOWN_MS);
        // The cooldown must outlast both the continue and idle scan intervals, or the
        // passive scan would re-select the session on the next cycle (the bug).
        assert!(BACKGROUND_COPY_SUCCESS_COOLDOWN_MS > BACKGROUND_COPY_IDLE_MS);
        assert!(BACKGROUND_COPY_SUCCESS_COOLDOWN_MS > BACKGROUND_COPY_CONTINUE_MS);
        // Within the cooldown the passive scan refuses to re-select.
        assert!(!background_copy_job_retry_ready(
            &retry_after,
            &passive_failures,
            "title",
            "remote-session://dev/test",
            now + BACKGROUND_COPY_IDLE_MS,
        ));
        // After the cooldown it may re-check.
        assert!(background_copy_job_retry_ready(
            &retry_after,
            &passive_failures,
            "title",
            "remote-session://dev/test",
            now + BACKGROUND_COPY_SUCCESS_COOLDOWN_MS + 1,
        ));
    }
    // Regression guard for the no-usable-title LLM loop (2026-06-15): empty-context
    // sessions must back off exponentially, not retry every 5 min forever.
    #[test]
    fn no_title_backoff_is_exponential_and_capped() {
        assert_eq!(no_title_backoff_ms(0), BACKGROUND_COPY_RETRY_MS); // 5m
        assert_eq!(no_title_backoff_ms(1), BACKGROUND_COPY_RETRY_MS * 2); // 10m
        assert_eq!(no_title_backoff_ms(2), BACKGROUND_COPY_RETRY_MS * 4); // 20m
        assert_eq!(no_title_backoff_ms(3), BACKGROUND_COPY_RETRY_MS * 8); // 40m
        assert_eq!(no_title_backoff_ms(4), BACKGROUND_COPY_NO_TITLE_BACKOFF_CAP_MS); // 80m cap
        // Beyond the cap it stays capped (and never overflows on a huge streak).
        assert_eq!(no_title_backoff_ms(5), BACKGROUND_COPY_NO_TITLE_BACKOFF_CAP_MS);
        assert_eq!(no_title_backoff_ms(99), BACKGROUND_COPY_NO_TITLE_BACKOFF_CAP_MS);
        assert_eq!(no_title_backoff_ms(u32::MAX), BACKGROUND_COPY_NO_TITLE_BACKOFF_CAP_MS);
        // The cap is a real reduction vs the flat retry: >= 16x the base interval.
        assert!(BACKGROUND_COPY_NO_TITLE_BACKOFF_CAP_MS >= BACKGROUND_COPY_RETRY_MS * 16);
    }
    // Render-loop CPU fix (2026-06-16): the peek-only snapshot gate decides via this pure
    // predicate; it must agree exactly with whether retarget actually mutates, or the gate
    // either misses a real reschedule or wakes the root for a no-op.
    #[test]
    fn snapshot_retarget_predicate_gates_the_mutation() {
        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session("local://test"));
        let now = 1_000_000u64;
        // next_after == 0 -> never retargets, never mutates.
        shell.next_live_session_snapshot_after_ms = 0;
        assert!(!live_session_snapshot_retarget_would_fire(&shell, now));
        let before = shell.background_live_session_snapshot_skipped_noop_count;
        assert!(!retarget_stale_live_session_snapshot_due_if_interval_relaxed(
            &mut shell, now
        ));
        assert_eq!(
            shell.background_live_session_snapshot_skipped_noop_count, before,
            "predicate false must mean no mutation"
        );
        // Not yet due -> false.
        shell.next_live_session_snapshot_after_ms = now + 1;
        assert!(!live_session_snapshot_retarget_would_fire(&shell, now));
        // SSOT invariant: retarget fires (and mutates) IFF the predicate was true.
        let predicted = live_session_snapshot_retarget_would_fire(&shell, now);
        let fired = retarget_stale_live_session_snapshot_due_if_interval_relaxed(&mut shell, now);
        assert_eq!(predicted, fired, "retarget must agree with its peek predicate");
    }
    #[test]
    fn background_copy_snapshot_nudge_preserves_existing_cooldown() {
        let bootstrap = test_shell_bootstrap_with_active_session("local://test");
        let mut shell = ShellState::new(bootstrap);

        shell.request_background_copy_scan_if_unscheduled();
        assert!(shell.next_background_copy_scan_after_ms > 0);

        let cooldown = current_millis().saturating_add(15_000);
        shell.next_background_copy_scan_after_ms = cooldown;
        shell.request_background_copy_scan_if_unscheduled();
        assert_eq!(shell.next_background_copy_scan_after_ms, cooldown);
    }
