    #[test]
    fn deferred_refreshes_still_scan_unhealthy_machines_for_recovery() {
        // 2026-07-04 sleep/wake incident: with the user focused on a broken
        // terminal the deferral gate held for 18 minutes, so no machine ever
        // re-scanned and the sidebar stayed stale/not-green. Unhealthy (and
        // unknown) machines must bypass the deferral; Healthy machines keep
        // deferring.
        let machine = |key: &str, health: RemoteMachineHealth| RemoteMachineSnapshot {
            cli_presence: Vec::new(),
            apps: Vec::new(),
            machine_key: key.to_string(),
            label: key.to_string(),
            ssh_target: key.to_string(),
            prefix: None,
            remote_binary_expr: None,
            remote_deploy_state: RemoteDeployState::Ready,
            health,
            sessions: Vec::new(),
        };
        let machines = vec![
            machine("dev", RemoteMachineHealth::Cached),
            machine("oc", RemoteMachineHealth::Offline),
            machine("charts-webapp", RemoteMachineHealth::Healthy),
        ];
        let pending = vec![
            "dev".to_string(),
            "oc".to_string(),
            "charts-webapp".to_string(),
            "unknown-machine".to_string(),
        ];
        assert_eq!(
            filter_pending_refreshes_for_deferral(pending.clone(), false, &machines),
            pending,
            "not deferred: everything pending scans"
        );
        assert_eq!(
            filter_pending_refreshes_for_deferral(pending, true, &machines),
            vec![
                "dev".to_string(),
                "oc".to_string(),
                "unknown-machine".to_string()
            ],
            "deferred: only non-Healthy and unknown machines scan (recovery)"
        );
    }

    #[test]
    fn failed_remote_machine_refresh_backoff_caps_and_never_freezes_forever() {
        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session("local://active"));
        let first = record_remote_machine_refresh_failure(&mut shell, "oc");
        let second = record_remote_machine_refresh_failure(&mut shell, "oc");
        let third = record_remote_machine_refresh_failure(&mut shell, "oc");
        let fourth = record_remote_machine_refresh_failure(&mut shell, "oc");
        let fifth = record_remote_machine_refresh_failure(&mut shell, "oc");
        let sixth = record_remote_machine_refresh_failure(&mut shell, "oc");

        assert!(second > first);
        assert!(third > second);
        assert!(fourth > third);
        // 5th+ failures repeat the top-of-ladder delay; a permanent freeze
        // (u64::MAX) would drop the machine out of the truth stage for the
        // whole GUI lifetime, hiding every session created after the freeze.
        assert_eq!(remote_machine_refresh_backoff_ms(5), 900_000);
        assert_eq!(remote_machine_refresh_backoff_ms(200), 900_000);
        assert!(fifth < u64::MAX);
        assert!(sixth < u64::MAX);
        assert_eq!(shell.remote_machine_refresh_failures.get("oc"), Some(&6));
        assert!(
            pending_remote_machine_refreshes(
                &[RemoteMachineSnapshot {
                    cli_presence: Vec::new(),
                    apps: Vec::new(),
                    machine_key: "oc".to_string(),
                    label: "oc".to_string(),
                    ssh_target: "oc".to_string(),
                    prefix: None,
                    remote_binary_expr: None,
                    remote_deploy_state: RemoteDeployState::Ready,
                    health: RemoteMachineHealth::Offline,
                    sessions: Vec::new(),
                }],
                &[SshConnectTarget {
                    label: "oc".to_string(),
                    kind: SessionKind::SshShell,
                    ssh_target: "oc".to_string(),
                    prefix: None,
                    cwd: None,
                }],
                &[],
                &HashSet::new(),
                &shell.remote_machine_refresh_completed,
                &shell.remote_machine_refresh_retry_after_ms,
                current_millis(),
            )
            .is_empty()
        );
    }
