    #[test]
    fn the_reorder_reply_is_re_read_from_the_gui_and_never_composed_from_the_request() {
        // ⛔ STRUCTURAL, because "remember to re-read" is exactly the discipline
        // that failed. The verb shipped composing `rendered_order` from the
        // daemon's post-apply snapshot — which EQUALS the request whenever the
        // daemon accepted it — so a reversed control produced byte-different
        // input and identical output, and the owner watched an unmoved sidebar
        // for the third time in one night.
        //
        // ⚠ Needles are assembled from halves so this assertion cannot match
        // its own source text (field guide §7.4).
        //
        // ⚠ Retargeted when the reply moved into ONE shared builder shared by
        // `sessions reorder` and `sessions sort`. The guarantee did not move —
        // it got stronger, because now BOTH verbs inherit it from one place
        // instead of one verb hand-rolling it. Asserting on the old match arm
        // would have failed while the property held, which is the "locks
        // survive contract changes" trap: rewrite the lock to the new model,
        // never delete the guarantee.
        let source = SHELL_SOURCE;
        let builder = source
            .split(concat!("fn reorder_", "response("))
            .nth(1)
            .expect("the one reply builder for every verb that moves rows");
        let builder = &builder[..builder.len().min(4000)];

        assert!(
            builder.contains(concat!("\"rendered_order\": ", "after")),
            "`rendered_order` must BE the order re-read AFTER the apply"
        );
        assert!(
            !builder.contains(concat!("\"rendered_order\": ", "requested")),
            "`rendered_order` must never be the request echoed back — that is the \
             whole defect this verb was built to end, committed by this verb"
        );
        // `changed` must be a BEFORE/AFTER comparison, never a parse of the
        // daemon's reply.
        assert!(
            builder.contains(concat!("\"changed\": ", "after_subset != subset(&before)")),
            "`changed` must compare the re-read order against the one from before"
        );

        // And the re-read itself must come from the rows the sidebar draws, not
        // from the server model the daemon just overwrote.
        let reader = source
            .split(concat!("fn rendered_live_", "order("))
            .nth(1)
            .expect("the one reader of the rendered order");
        let reader = &reader[..reader.len().min(600)];
        assert!(
            reader.contains(concat!(".snapshot", "()")) && reader.contains(concat!(".", "rows")),
            "re-read the RENDERED rows; the daemon's own snapshot is what lied"
        );

        // Both row-moving verbs must go through the shared applier, so neither
        // can grow a private route that skips the drag's proven three steps.
        let applier = concat!("apply_live_order_the_way_a_", "drag_does(");
        assert!(
            source.matches(applier).count() >= 3,
            "reorder and sort must both call the one applier (plus its definition)"
        );
    }

    // ⛔ The refusal, and its three negative controls — each of which, if it
    // flipped, would break something that WORKS today.
    //
    // Measured live on guihost 2026-08-07 against a real Claude Code TUI: a
    // three-line `terminal send` submitted line 1 alone and left lines 2-3 as
    // "Press up to edit queued messages", while the reply reported
    // `accepted: true` with `chunk_count: 3`. The same payload into a plain bash
    // row ran all three commands correctly — which is why the SESSION KIND, not
    // the payload alone, decides.
    #[test]
    fn a_multiline_send_is_refused_for_an_agent_cli_and_allowed_for_a_shell() {
        let brief = "1. read the doors\n2. take item one\n3. report back\n";

        assert!(
            app_control_send_refuses_multiline(true, false, brief),
            "a brief into an agent composer is one Enter per line — refuse it by name"
        );

        // NEGATIVE 1 — a shell row. N lines are N commands and that is correct.
        assert!(
            !app_control_send_refuses_multiline(false, false, brief),
            "a shell row must keep accepting multi-line sends; heredocs and \
             command batches depend on it"
        );
        // NEGATIVE 2 — the caller opted in, knowing it fires N submits.
        assert!(!app_control_send_refuses_multiline(true, true, brief));
        // NEGATIVE 3 — the ordinary single-line drive, with and without Enter.
        assert!(!app_control_send_refuses_multiline(true, false, "/status\r"));
        assert!(!app_control_send_refuses_multiline(true, false, "/status"));
        assert!(!app_control_send_refuses_multiline(true, false, "\r"));
        // A bare interrupt carries no line break and must still reach a busy agent.
        assert!(!app_control_send_refuses_multiline(true, false, "\u{3}"));
    }

    #[test]
    fn app_control_terminal_input_splits_interrupt_from_following_bytes() {
        assert_eq!(
            app_control_terminal_input_write_chunks("\u{3}\u{5}\u{15}"),
            vec!["\u{3}".to_string(), "\u{5}\u{15}".to_string()]
        );
        assert_eq!(
            app_control_terminal_input_write_chunks("echo ok\r"),
            vec!["echo ok\r".to_string()]
        );
        assert_eq!(
            app_control_terminal_input_write_chunks("/status\r\n"),
            vec!["/status\r".to_string()]
        );
        assert_eq!(
            app_control_terminal_input_write_chunks("before\u{3}after\n"),
            vec![
                "before".to_string(),
                "\u{3}".to_string(),
                "after\r".to_string()
            ]
        );
        assert_eq!(
            app_control_terminal_input_write_chunks("\u{3}"),
            vec!["\u{3}".to_string()]
        );
        let heredoc = "python3 - <<'PY'\nprint('ready')\nPY\n";
        assert_eq!(
            app_control_terminal_input_write_chunks(heredoc),
            vec![
                "python3 - <<'PY'\r".to_string(),
                "print('ready')\r".to_string(),
                "PY\r".to_string()
            ],
            "multiline app-control pastes must be paced as line writes with terminal-enter semantics, so background heredocs cannot block the PTY echo path before the terminator line"
        );
        // A bracketed-paste block stays ONE write. Splitting it would put a 25 ms
        // settle in the middle of a paste — and the whole reason the block exists
        // is that there is no Enter inside it to pace.
        let pasted = format!(
            "{}line one\nline two\nline three{}",
            yggterm_core::terminal_input::BRACKETED_PASTE_BEGIN,
            yggterm_core::terminal_input::BRACKETED_PASTE_END
        );
        assert_eq!(
            app_control_terminal_input_write_chunks(&pasted),
            vec![format!(
                "{}line one\rline two\rline three{}",
                yggterm_core::terminal_input::BRACKETED_PASTE_BEGIN,
                yggterm_core::terminal_input::BRACKETED_PASTE_END
            )],
            "a bracketed-paste block is one write; its interior \\r are soft newlines in the composer, not Enters"
        );
        assert_eq!(
            app_control_terminal_input_read_nudge_reason("echo ok\r"),
            APP_CONTROL_TERMINAL_SEND_REASON
        );
        assert_eq!(
            app_control_terminal_input_read_nudge_reason(heredoc),
            APP_CONTROL_TERMINAL_MULTILINE_SEND_REASON
        );
        assert_eq!(
            terminal_read_nudge_burst_reads(APP_CONTROL_TERMINAL_MULTILINE_SEND_REASON, false),
            TERMINAL_APP_CONTROL_MULTILINE_READ_BURST_READS
        );
        assert_eq!(
            terminal_read_nudge_burst_reads(APP_CONTROL_TERMINAL_MULTILINE_SEND_REASON, true),
            TERMINAL_APP_CONTROL_BACKGROUND_MULTILINE_READ_BURST_READS
        );
        assert_eq!(
            terminal_read_nudge_burst_reads(APP_CONTROL_TERMINAL_SEND_REASON, true),
            TERMINAL_INPUT_ECHO_READ_BURST_READS
        );
    }
