    /// ⭐ THE SCOPE RANKS, IT DOES NOT DROP — and this test used to assert the
    /// opposite, which is how it caught the change honestly.
    ///
    /// It was `..._excludes_remote_same_cwd`, and the exclusion it locked in is
    /// exactly the bug the owner hit on 2026-08-08: he removed a delegate row,
    /// went to the start page to reopen it, and it was not there. Measured that
    /// day, one page read three times with a different row selected answered
    /// **188 shown, then 40, then 4** — the list is scoped to the selected row's
    /// `{machine_key, cwd}` and the header says only "N shown", so a filtered
    /// row and a nonexistent one look identical.
    ///
    /// So the two facts are now asserted TOGETHER, because either alone is the
    /// wrong behaviour: the in-scope local rows still LEAD (the page promises
    /// "create work in this scope" and that ordering is what makes it true), and
    /// the out-of-scope remote rows are still PRESENT, at the end, where they
    /// can be found.
    #[test]
    fn start_page_recent_rows_scope_ranks_out_of_scope_rows_last_instead_of_dropping_them() {
        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session("local://seed"));
        let remote_session =
            |machine: &str, name: &str, cwd: &str, modified_epoch: i64| RemoteScannedSession {
                kind: None,
                session_path: format!("remote-session://{machine}/{name}"),
                session_id: name.to_string(),
                cwd: cwd.to_string(),
                started_at: format!("2026-05-05T{modified_epoch}:00:00Z"),
                modified_epoch,
                event_count: 1,
                user_message_count: 1,
                assistant_message_count: 0,
                title_hint: name.to_string(),
                recent_context: String::new(),
                cached_precis: None,
                cached_summary: None,
                live_runtime: false,
                title_is_explicit: false,
                storage_path: format!("/home/user/.codex/sessions/{name}.jsonl"),
            };
        shell.server.apply_snapshot(ServerUiSnapshot {
            apps: Vec::new(),
            active_session_path: None,
            active_session: None,
            active_view_mode: WorkspaceViewMode::Rendered,
            remote_machines: vec![
                RemoteMachineSnapshot {
                    cli_presence: Vec::new(),
                    apps: Vec::new(),
                    machine_key: "dev".to_string(),
                    label: "dev".to_string(),
                    ssh_target: "pi@dev".to_string(),
                    prefix: None,
                    remote_binary_expr: None,
                    remote_deploy_state: RemoteDeployState::Ready,
                    health: RemoteMachineHealth::Healthy,
                    sessions: vec![remote_session("dev", "dev-home", "/home/user", 50)],
                },
                RemoteMachineSnapshot {
                    cli_presence: Vec::new(),
                    apps: Vec::new(),
                    machine_key: "practice".to_string(),
                    label: "practice".to_string(),
                    ssh_target: "pi@practice".to_string(),
                    prefix: None,
                    remote_binary_expr: None,
                    remote_deploy_state: RemoteDeployState::Ready,
                    health: RemoteMachineHealth::Healthy,
                    sessions: vec![remote_session("practice", "practice-home", "/home/user", 60)],
                },
            ],
            ssh_targets: Vec::new(),
            live_sessions: Vec::new(),
        });
        let mut snapshot = shell.snapshot();
        snapshot.selected_row = Some(BrowserRow {
            kind: BrowserRowKind::Group,
            full_path: "/home/user".to_string(),
            label: "home/pi".to_string(),
            detail_label: String::new(),
            document_kind: None,
            group_kind: None,
            session_title: None,
            depth: 1,
            host_label: String::new(),
            descendant_sessions: 2,
            expanded: true,
            session_id: None,
            session_cwd: Some("/home/user".to_string()),
            session_kind: None,
        });
        let visible_rows = vec![snapshot.selected_row.clone().unwrap()];
        let all_rows = vec![
            visible_rows[0].clone(),
            test_browser_session_row(
                "/home/user/.codex/sessions/local-old.jsonl",
                "local-old",
                "",
                Some("/home/user"),
            ),
            test_browser_session_row(
                "/home/user/.codex/sessions/local-child.jsonl",
                "local-child",
                "",
                Some("/home/user/gh/yggterm"),
            ),
            test_browser_session_row(
                "/home/user/.codex/sessions/local-newer.jsonl",
                "local-newer",
                "",
                Some("/home/user"),
            ),
        ];
        snapshot.rows = visible_rows;

        let paths = start_page_recent_rows_from_browser_rows_with_modified_epochs(
            &snapshot,
            &all_rows,
            |row| match row.label.as_str() {
                "local-newer" => 30,
                "local-child" => 20,
                "local-old" => 10,
                _ => 0,
            },
        )
        .into_iter()
        .map(|row| row.full_path)
        .collect::<Vec<_>>();

        assert_eq!(
            paths,
            [
                // In scope, by recency — the head of the list is unchanged.
                "/home/user/.codex/sessions/local-newer.jsonl",
                "/home/user/.codex/sessions/local-child.jsonl",
                "/home/user/.codex/sessions/local-old.jsonl",
                // Out of scope, still listed, by recency among themselves. These
                // two used to be DROPPED — and a dropped row is indistinguishable
                // from one that does not exist, which is the whole bug.
                "remote-session://practice/practice-home",
                "remote-session://dev/dev-home",
            ]
        );
    }

    /// ⛔ A text input fed from the SNAPSHOT must never use volatile `value:`.
    ///
    /// This is a source-level lock on the bug the owner hit on 2026-08-06:
    /// typing one character into the session rename box threw the caret to the
    /// end of the line. `value` is declared `volatile` in dioxus-html, so it is
    /// re-applied to the DOM on every render; `rename_value` arrives from
    /// `snapshot.tree_rename_value`, a projection rebuilt asynchronously. So
    /// between the keystroke and the next snapshot rebuild, a render re-asserted
    /// the STALE text, the interpreter saw `node.value !== value` and rewrote
    /// the node — which resets the caret. Two owners for one string while the
    /// user is typing, which is the repo's single-source-of-truth rule broken in
    /// the one place where the DOM is the authority.
    ///
    /// `initial_value` seeds the field once and then leaves it alone; `oninput`
    /// keeps the host in step for the commit. Every other text field in this
    /// file already did it that way — the rename box was the outlier.
    ///
    /// The lock scans the source rather than the rendered DOM because there is
    /// no headless way to observe a caret, and because the failure is invisible
    /// until a human types in the MIDDLE of a word.
    #[test]
    fn no_snapshot_fed_text_input_uses_the_volatile_value_attribute() {
        let source = SHELL_SOURCE;
        let lines = source.lines().collect::<Vec<_>>();
        let mut offenders = Vec::new();
        for (index, line) in lines.iter().enumerate() {
            let trimmed = line.trim();
            // Only RAW elements. A `value:` on a component is an ordinary prop
            // name and carries none of this meaning.
            if trimmed != "input {" && trimmed != "textarea {" {
                continue;
            }
            let mut depth = 1_i32;
            let mut cursor = index + 1;
            while cursor < lines.len() && depth > 0 {
                let body = lines[cursor];
                depth += body.matches('{').count() as i32;
                depth -= body.matches('}').count() as i32;
                if depth > 0 {
                    let body = body.trim_start();
                    if let Some(rest) = body.strip_prefix("value:") {
                        // Only the snapshot-fed ones. A slider or colour well
                        // genuinely wants the host to drive it, and has no
                        // caret to lose.
                        if rest.contains("snapshot.") || rest.contains("rename_value") {
                            offenders.push(format!("line {}: {}", cursor + 1, body));
                        }
                    }
                }
                cursor += 1;
            }
        }
        assert!(
            offenders.is_empty(),
            "these inputs re-assert a lagging snapshot value on every render and \
             will throw the caret to the end mid-typing — use `initial_value:`:\n{}",
            offenders.join("\n")
        );
    }

    /// The face must be the member last RUN, and it must survive a restart.
    ///
    /// The owner's requirement, verbatim: "The button names are sticky. Maning
    /// if I last press it to open claude code it will stay there." A choice
    /// that resets on relaunch is a default, not a sticky face, so the
    /// assertion that matters is the one about `AppSettings` — the persisted
    /// record, which is what the first frame after a restart reads.
    #[test]
    fn the_start_page_split_button_face_is_the_member_last_run_and_persists() {
        let mut shell = ShellState::new(test_shell_bootstrap_with_start_page());
        assert_eq!(shell.settings.start_page_session_choice, None);
        assert_eq!(shell.settings.start_page_app_choice, None);

        shell.remember_start_page_choice(StartPageFamily::Session, "claude-code");
        assert_eq!(
            shell.settings.start_page_session_choice.as_deref(),
            Some("claude-code"),
            "pressing Claude Code must move the face to Claude Code"
        );

        // The two families are independent: choosing an app must not disturb
        // the session face, or opening a browser would silently re-aim the
        // button the user starts work with.
        shell.remember_start_page_choice(StartPageFamily::App, "app:ychrome:open");
        assert_eq!(
            shell.settings.start_page_session_choice.as_deref(),
            Some("claude-code")
        );
        assert_eq!(
            shell.settings.start_page_app_choice.as_deref(),
            Some("app:ychrome:open")
        );

        // The persisted settings ARE the sticky record — this is the value a
        // fresh process reads to paint the first frame.
        let restored: AppSettings =
            serde_json::from_str(&serde_json::to_string(&shell.settings).expect("encode"))
                .expect("decode");
        assert_eq!(
            restored.start_page_session_choice.as_deref(),
            Some("claude-code"),
            "the choice must survive a serialize/restore round trip"
        );
        assert_eq!(
            restored.start_page_app_choice.as_deref(),
            Some("app:ychrome:open")
        );

        // An empty id is not a choice and must not blank the face.
        shell.remember_start_page_choice(StartPageFamily::Session, "   ");
        assert_eq!(
            shell.settings.start_page_session_choice.as_deref(),
            Some("claude-code")
        );
    }

    /// Seven buttons became two controls, and every action the row offered is
    /// still reachable — a tidier row that dropped a verb would be a
    /// regression wearing a redesign.
    #[test]
    fn both_start_page_families_still_offer_every_action_the_old_row_had() {
        let session = start_page_session_items("#2563eb");
        let ids = session.iter().map(|i| i.id.as_str()).collect::<Vec<_>>();
        // DERIVED: one member per registered agent CLI, and NOTHING else.
        // Transcribing the shipped ids here made the lock stop describing the
        // family the moment a CLI was added.
        let expected: Vec<&str> = yggterm_core::agent_cli::AGENT_CLIS
            .iter()
            .map(|descriptor| descriptor.slug)
            .collect();
        assert_eq!(ids, expected);
        assert!(ids.contains(&"codex") && ids.contains(&"claude-code"));
        // ⛔ The plain shell is NOT a member (owner directive 2026-08-08). Being
        // in the family means being STICKY, so a shell chosen once became the
        // face of the button people reach for to start an agent. It has its own
        // button now; a member that carries no accent is the shape of the bug
        // coming back, because every agent CLI has one.
        assert!(
            !ids.contains(&"terminal"),
            "a plain shell must not be a member of the sticky session family"
        );
        for item in &session {
            assert!(
                !item.accent.trim().is_empty(),
                "{} is in the session family and must therefore be an agent CLI, \
                 which carries an accent",
                item.id
            );
        }

        let apps = vec![AppManifest {
            name: "ychrome".to_string(),
            icon: "🌐".to_string(),
            verbs: vec![AppVerb {
                id: "open".to_string(),
                label: "New Ychrome".to_string(),
                ..Default::default()
            }],
            ..Default::default()
        }];
        let app_items = start_page_app_items(&apps);
        assert_eq!(app_items.len(), 1);
        assert_eq!(app_items[0].id, "app:ychrome:open");
        assert!(
            app_items[0].label.contains("New Ychrome"),
            "the verb label carries through; got {:?}",
            app_items[0].label
        );
    }

    #[test]
    fn start_page_recent_rows_keep_live_sessions_so_the_page_cannot_lie() {
        // SPEC (user directive 2026-08-06): a running session KEEPS its start
        // page row. This test previously asserted the OPPOSITE — that the live
        // row is stripped — under the 2026-05-26 call recorded in
        // [[spec-active-sessions-dual-presence]], whose stated premise was that
        // live sessions are "already accessible from the sidebar Live Sessions
        // group". When a daemon-reachability bug emptied that group, the strip
        // meant the running sessions appeared NOWHERE, and launching a session
        // made its own card disappear. The user's words: "If the session is
        // open it should switch to that not LIE about sessions present."
        //
        // The old assertion is kept below, inverted, so the reversal is legible
        // rather than looking like a deleted test.
        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session("local://seed"));
        let live_terminal_path = "live::remote-shell";
        let mut live_terminal = test_live_shell_session(live_terminal_path);
        live_terminal.id = "remote-shell".to_string();
        live_terminal.kind = SessionKind::Codex;
        live_terminal.source = SessionSource::LiveSsh;
        live_terminal.host_label = "samplenotes-webapp".to_string();
        live_terminal.ssh_target = Some("pi@samplenotes-webapp".to_string());
        live_terminal.metadata = vec![
            SessionMetadataEntry {
                label: "Target",
                value: "samplenotes-webapp".to_string(),
            },
            SessionMetadataEntry {
                label: "Cwd",
                value: "/home/user".to_string(),
            },
        ];
        shell.server.apply_snapshot(ServerUiSnapshot {
            active_session_path: None,
            active_session: None,
            active_view_mode: WorkspaceViewMode::Rendered,
            remote_machines: Vec::new(),
            ssh_targets: Vec::new(),
            live_sessions: vec![snapshot_session_view_for_ui(live_terminal.clone())],
            apps: Vec::new(),
        });
        let mut snapshot = shell.snapshot();
        snapshot.selected_row = Some(BrowserRow {
            kind: BrowserRowKind::Group,
            full_path: "__remote_folder__/samplenotes-webapp/home/user".to_string(),
            label: "/home/user".to_string(),
            detail_label: String::new(),
            document_kind: None,
            group_kind: Some(WorkspaceGroupKind::Folder),
            session_title: None,
            depth: 1,
            host_label: "samplenotes-webapp".to_string(),
            descendant_sessions: 1,
            expanded: true,
            session_id: None,
            session_cwd: Some("/home/user".to_string()),
            session_kind: None,
        });
        snapshot.rows = vec![
            snapshot.selected_row.clone().unwrap(),
            {
                let mut row = test_browser_session_row(
                    live_terminal_path,
                    "samplenotes-webapp",
                    "samplenotes-webapp",
                    Some("/home/user"),
                );
                row.session_kind = Some(SessionKind::Codex);
                row
            },
            test_browser_session_row(
                "remote-session://samplenotes-webapp/durable",
                "Durable Codex",
                "samplenotes-webapp",
                Some("/home/user"),
            ),
        ];

        let paths = start_page_recent_rows_from_browser_rows(&snapshot, &snapshot.rows)
            .into_iter()
            .map(|row| row.full_path)
            .collect::<Vec<_>>();

        // The live row now SURVIVES, and it sorts ahead of the durable scanned
        // row because live rows are pushed first. Before the 2026-08-06 fix
        // this asserted `["remote-session://samplenotes-webapp/durable"]` — the
        // live session had been silently dropped off the page.
        assert!(
            paths.contains(&live_terminal_path.to_string()),
            "a running session must keep its start page row; got {paths:?}"
        );
        assert_eq!(
            paths
                .iter()
                .filter(|path| path.as_str() == live_terminal_path)
                .count(),
            1,
            "and it must appear exactly ONCE — one session, one card"
        );
        assert!(
            paths.contains(&"remote-session://samplenotes-webapp/durable".to_string()),
            "the durable scanned session is unaffected; got {paths:?}"
        );
    }

    #[test]
    fn a_live_session_and_its_stored_transcript_collapse_to_the_live_row() {
        // One session wearing two paths — `local://<id>` while running and a
        // stored transcript row from the scan — must be ONE card, and the card
        // must be the live one so that opening it focuses the running session
        // instead of starting a second copy of it.
        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session("local://seed"));
        let live_path = "local://shared-session-id";
        let mut live = test_live_shell_session(live_path);
        live.id = "shared-session-id".to_string();
        live.kind = SessionKind::Codex;
        shell.server.apply_snapshot(ServerUiSnapshot {
            active_session_path: None,
            active_session: None,
            active_view_mode: WorkspaceViewMode::Rendered,
            remote_machines: Vec::new(),
            ssh_targets: Vec::new(),
            live_sessions: vec![snapshot_session_view_for_ui(live)],
            apps: Vec::new(),
        });
        let mut snapshot = shell.snapshot();
        // No selected row → unscoped recents, so this test measures the dedup
        // and nothing else.
        snapshot.selected_row = None;
        snapshot.active_session_path = None;

        let mut live_row =
            test_browser_session_row(live_path, "Shared", "local", Some("/home/user"));
        live_row.session_id = Some("shared-session-id".to_string());
        live_row.session_kind = Some(SessionKind::Codex);
        let mut stored_row = test_browser_session_row(
            "/home/user/.codex/sessions/shared-session-id.jsonl",
            "Shared",
            "local",
            Some("/home/user"),
        );
        stored_row.session_id = Some("shared-session-id".to_string());
        snapshot.rows = vec![stored_row, live_row];

        let paths = start_page_recent_rows_from_browser_rows(&snapshot, &snapshot.rows)
            .into_iter()
            .map(|row| row.full_path)
            .collect::<Vec<_>>();

        assert_eq!(
            paths,
            [live_path],
            "the pair must collapse to the LIVE row, not the stored transcript"
        );
    }

