    #[test]
    fn user_collapsed_synthetic_paths_persist_and_block_auto_seeding() {
        // A collapse of a synthetic group (machine root / Live Sessions) must
        // survive a GUI restart: it persists into settings, restores into the
        // new ShellState, blocks restore-time expansion of the same path, and
        // blocks the dynamic top-level auto-seed from re-expanding it.
        let mut bootstrap = test_shell_bootstrap_with_active_session("local://fresh-shell");
        bootstrap.settings.expanded_browser_paths = vec![
            "__live_sessions__".to_string(),
            "__remote_machine__/practice".to_string(),
            "__remote_machine__/dev".to_string(),
        ];
        bootstrap.settings.collapsed_synthetic_paths =
            vec!["__remote_machine__/practice".to_string()];
        let mut shell = ShellState::new(bootstrap);
        // Restored collapse outranks the stale expanded entry.
        assert!(
            shell
                .user_collapsed_synthetic_paths
                .contains("__remote_machine__/practice")
        );
        assert!(
            !shell
                .browser
                .expanded_path_set()
                .contains("__remote_machine__/practice")
        );
        assert!(
            shell
                .browser
                .expanded_path_set()
                .contains("__remote_machine__/dev")
        );
        // The auto-seed never re-expands a user-collapsed synthetic path.
        shell
            .user_collapsed_synthetic_paths
            .insert("__live_sessions__".to_string());
        shell.browser.toggle_virtual_group("__live_sessions__");
        shell.seed_dynamic_top_level_expansions();
        assert!(
            !shell
                .browser
                .expanded_path_set()
                .contains("__live_sessions__")
        );
        // sync_browser_settings round-trips the collapse set into settings.
        shell.sync_browser_settings();
        assert!(
            shell
                .settings
                .collapsed_synthetic_paths
                .contains(&"__live_sessions__".to_string())
        );
        assert!(
            shell
                .settings
                .collapsed_synthetic_paths
                .contains(&"__remote_machine__/practice".to_string())
        );
        // Expanding again clears the collapse (and would persist the clear).
        shell.update_synthetic_group_collapse_state("__remote_machine__/practice", true);
        shell.sync_browser_settings();
        assert!(
            !shell
                .settings
                .collapsed_synthetic_paths
                .contains(&"__remote_machine__/practice".to_string())
        );
    }

    #[test]
    fn collapsed_local_root_survives_background_tree_rebuild() {
        // Regression: the ~8-15s daemon background refresh rebuilds the browser
        // via `restore_browser_tree_preserving_sidebar_view`, which constructs a
        // fresh `SessionBrowserState` (empty collapse mirror). Before the fix the
        // default level-one seeding re-opened the user-collapsed "local" machine
        // root on every refresh, so the tree never stayed collapsed even though
        // the collapse was persisted (finding-sidebar-collapse-not-persisted).
        let local_root = SessionNode {
            kind: SessionNodeKind::Group,
            name: "local".to_string(),
            path: PathBuf::from("local"),
            children: vec![SessionNode {
                kind: SessionNodeKind::CodexSession,
                name: "session".to_string(),
                path: PathBuf::from("/home/user/.codex/sessions/x.jsonl"),
                session_id: Some("x".to_string()),
                cwd: Some("/home/user".to_string()),
                ..Default::default()
            }],
            ..Default::default()
        };
        let root = SessionNode {
            kind: SessionNodeKind::Group,
            name: "root".to_string(),
            path: PathBuf::from("/"),
            children: vec![local_root],
            ..Default::default()
        };
        let mut bootstrap = test_shell_bootstrap_with_browser_tree(root.clone());
        bootstrap.settings.collapsed_synthetic_paths = vec!["local".to_string()];
        let mut shell = ShellState::new(bootstrap);
        // Construction honors the persisted collapse.
        assert!(
            shell.user_collapsed_synthetic_paths.contains("local"),
            "collapse SSOT seeded from settings"
        );
        assert!(
            !shell.browser.expanded_path_set().contains("local"),
            "local root starts collapsed after construction"
        );
        // A background tree rebuild (the daemon refresh) must NOT re-expand it.
        restore_browser_tree_preserving_sidebar_view(&mut shell, root.clone(), None);
        assert!(
            !shell.browser.expanded_path_set().contains("local"),
            "local root stays collapsed across a background rebuild"
        );
        // Re-running the rebuild repeatedly (the periodic refresh) keeps it collapsed.
        restore_browser_tree_preserving_sidebar_view(&mut shell, root, None);
        assert!(
            !shell.browser.expanded_path_set().contains("local"),
            "local root stays collapsed across repeated background rebuilds"
        );
    }

