    #[test]
    fn sync_live_terminal_retention_keeps_active_not_fresh_inactive_live_sessions() {
        let active_path = "remote-session://dev/active";
        let inactive_path = "remote-session://dev/inactive";
        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session(active_path));
        let mut active_session = test_live_shell_session(active_path);
        active_session.id = "active-remote".to_string();
        active_session.title = "Active Remote".to_string();
        active_session.source = SessionSource::LiveSsh;
        active_session.host_label = "dev".to_string();
        active_session.ssh_target = Some("dev".to_string());
        let mut inactive_session = test_live_shell_session(inactive_path);
        inactive_session.id = "inactive-remote".to_string();
        inactive_session.title = "Inactive Remote".to_string();
        inactive_session.source = SessionSource::LiveSsh;
        inactive_session.host_label = "dev".to_string();
        inactive_session.ssh_target = Some("dev".to_string());
        shell.server.apply_snapshot(ServerUiSnapshot {
            apps: Vec::new(),
            active_session_path: Some(active_path.to_string()),
            active_session: Some(snapshot_session_view_for_ui(active_session.clone())),
            active_view_mode: WorkspaceViewMode::Terminal,
            remote_machines: Vec::new(),
            ssh_targets: Vec::new(),
            live_sessions: vec![
                snapshot_session_view_for_ui(active_session),
                snapshot_session_view_for_ui(inactive_session),
            ],
        });

        shell.sync_live_terminal_retention();
        let snapshot = shell.snapshot();
        let retained_paths = snapshot
            .retained_terminal_sessions
            .iter()
            .map(|session| session.session_path.as_str())
            .collect::<HashSet<_>>();
        assert!(retained_paths.contains(active_path));
        assert!(
            !retained_paths.contains(inactive_path),
            "fresh inactive live runtimes must stay in daemon truth/sidebar without mounting hidden xterm hosts"
        );
        assert!(
            snapshot
                .live_sessions
                .iter()
                .any(|session| session.session_path == inactive_path),
            "inactive kept runtimes must remain visible in Live Sessions"
        );

        shell.retain_terminal_session_path(inactive_path);
        shell
            .terminal_resume_ready_paths
            .insert(inactive_path.to_string());
        shell.sync_live_terminal_retention();
        let snapshot = shell.snapshot();
        assert!(
            snapshot
                .retained_terminal_sessions
                .iter()
                .any(|session| session.session_path == inactive_path),
            "inactive live sessions with current render state should stay mounted"
        );
    }

    #[test]
    fn sync_live_terminal_retention_drops_retained_remote_when_snapshot_loses_runtime() {
        let remote_path = "remote-session://dev/019dbdc7-7e63-7211-a7f8-51eb4d6e80b2";
        let local_path = "local://active-shell";
        let mut shell = ShellState::new(test_shell_bootstrap_with_active_session(remote_path));
        let mut remote_session = test_live_shell_session(remote_path);
        remote_session.id = "remote-codex".to_string();
        remote_session.title = "Remote Codex".to_string();
        remote_session.kind = SessionKind::Codex;
        remote_session.host_label = "dev".to_string();
        remote_session.source = SessionSource::LiveSsh;
        remote_session.bridge_available = true;
        remote_session.ssh_target = Some("dev".to_string());
        remote_session.status_line = "› Improve documentation in @filename".to_string();
        remote_session.terminal_lines = vec![remote_session.status_line.clone()];
        let mut local_session = test_live_shell_session(local_path);
        local_session.id = "local-shell".to_string();
        shell.server.apply_snapshot(ServerUiSnapshot {
            active_session_path: Some(remote_path.to_string()),
            active_session: Some(snapshot_session_view_for_ui(remote_session.clone())),
            active_view_mode: WorkspaceViewMode::Terminal,
            remote_machines: Vec::new(),
            ssh_targets: Vec::new(),
            live_sessions: vec![snapshot_session_view_for_ui(remote_session.clone())],
            apps: Vec::new(),
        });
        shell.refresh_cached_hot_session_views();
        let attempt_id =
            shell.begin_terminal_open_attempt(remote_path, "remote-open", 1, "startup_restore");
        shell.retain_terminal_session_path(remote_path);
        shell
            .terminal_resume_ready_paths
            .insert(remote_path.to_string());
        shell.mark_terminal_open_attempt_ready_for_session(remote_path, "visual_reveal");
        assert!(matches!(
            shell
                .terminal_open_attempts
                .get(&attempt_id)
                .map(|attempt| &attempt.state),
            Some(TerminalOpenAttemptState::Ready)
        ));

        shell.server.apply_snapshot(ServerUiSnapshot {
            active_session_path: Some(local_path.to_string()),
            active_session: Some(snapshot_session_view_for_ui(local_session.clone())),
            active_view_mode: WorkspaceViewMode::Terminal,
            remote_machines: Vec::new(),
            ssh_targets: Vec::new(),
            live_sessions: vec![snapshot_session_view_for_ui(local_session)],
            apps: Vec::new(),
        });
        shell.refresh_cached_hot_session_views();
        shell.sync_live_terminal_retention();

        assert!(
            !shell.retained_terminal_session_paths.contains(remote_path),
            "retained terminal hosts must not preserve a live session after daemon runtime truth omits it"
        );
        let snapshot = shell.snapshot();
        assert!(
            !snapshot
                .retained_terminal_sessions
                .iter()
                .any(|session| session.session_path == remote_path),
            "cached retained remote must not keep rendering after runtime loss"
        );
    }

